(function(){var m=window.SITE_DATA_BY_DOMAIN||{};var d=m["multimodal"]||{};var a=d["papers"]||[];for(var i=0;i<a.length;i++){if(a[i].id=="paper-duet-vlm-dual-stage-unified-efficien-2026"){a[i]["long_html"]="<nav class=\"long-toc\"><b>本页目录</b><ol><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-duet-vlm-dual-stage-unified-efficien-2026-sec-1\">一 · 一个被视觉 token 拖垮的在线服务现场</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-duet-vlm-dual-stage-unified-efficien-2026-sec-2\">二 · 旧方案的两条路线与它们的结构性缺口</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-duet-vlm-dual-stage-unified-efficien-2026-sec-3\">三 · 代价核算：预填算力、KV 显存与批调度粒度</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-duet-vlm-dual-stage-unified-efficien-2026-sec-4\">四 · 为什么单阶段压缩在 Blackwell 档位上失效</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-duet-vlm-dual-stage-unified-efficien-2026-sec-5\">五 · 两阶段串联如何把压缩变成可调度对象</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-duet-vlm-dual-stage-unified-efficien-2026-sec-6\">六 · 遗留的工程缺口与部署时必须自己补的量</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-duet-vlm-dual-stage-unified-efficien-2026-sec-7\">七 · 在线服务的预填墙：单阶段压缩为何在 Blackwell 档位上失效</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-duet-vlm-dual-stage-unified-efficien-2026-sec-8\">八 · 请求长度分布：压缩比把长尾切成什么形状</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-duet-vlm-dual-stage-unified-efficien-2026-sec-9\">九 · 并发与批大小：压缩后长度是显存估算的唯一粒度</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-duet-vlm-dual-stage-unified-efficien-2026-sec-10\">十 · SLO 与长尾：预填延迟的两个来源</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-duet-vlm-dual-stage-unified-efficien-2026-sec-11\">十一 · 负载如何反向约束方案设计</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-duet-vlm-dual-stage-unified-efficien-2026-sec-12\">十二 · 可核查的测量口径清单</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-duet-vlm-dual-stage-unified-efficien-2026-sec-13\">十三 · 压缩比作为负载整形旋钮：边界、失效与可核查口径</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-duet-vlm-dual-stage-unified-efficien-2026-sec-14\">十四 · 两阶段压缩算子的 kernel 形态与数值路径</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-duet-vlm-dual-stage-unified-efficien-2026-sec-15\">十五 · 数据类型选择：FP16、BF16、FP8 与 NVFP4 的分工</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-duet-vlm-dual-stage-unified-efficien-2026-sec-16\">十六 · Blackwell 特性：tcgen05、TMEM 与 2-SM MMA 对压缩算子的意义</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-duet-vlm-dual-stage-unified-efficien-2026-sec-17\">十七 · 累加精度与误差传播：从合并到 KV cache</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-duet-vlm-dual-stage-unified-efficien-2026-sec-18\">十八 · 量化与压缩算子的兼容性缺口</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-duet-vlm-dual-stage-unified-efficien-2026-sec-19\">十九 · 精度路径的工程判断</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-duet-vlm-dual-stage-unified-efficien-2026-sec-20\">二十 · 从“全量视觉 token”出发的显存账本</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-duet-vlm-dual-stage-unified-efficien-2026-sec-21\">二十一 · 分页与压缩后长度的对齐</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-duet-vlm-dual-stage-unified-efficien-2026-sec-22\">二十二 · 带宽瓶颈：预填算力与解码 KV 读</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-duet-vlm-dual-stage-unified-efficien-2026-sec-23\">二十三 · 复用与卸载：压缩后 KV 的层级放置</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-duet-vlm-dual-stage-unified-efficien-2026-sec-24\">二十四 · HBM3e 容量怎么算与预算模板</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-duet-vlm-dual-stage-unified-efficien-2026-sec-25\">二十五 · 压缩比、精度与调度的联合约束</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-duet-vlm-dual-stage-unified-efficien-2026-sec-26\">二十六 · 压缩比落进显存账本：KV 分配粒度与带宽拐点</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-duet-vlm-dual-stage-unified-efficien-2026-sec-27\">二十七 · 压缩后 token 数作为调度原语</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-duet-vlm-dual-stage-unified-efficien-2026-sec-28\">二十八 · 连续批处理在压缩序列上的迭代粒度</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-duet-vlm-dual-stage-unified-efficien-2026-sec-29\">二十九 · chunked prefill 与压缩序列的切分点</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-duet-vlm-dual-stage-unified-efficien-2026-sec-30\">三十 · 优先级、抢占与压缩比的联合决策</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-duet-vlm-dual-stage-unified-efficien-2026-sec-31\">三十一 · 分离式预填/解码下的压缩位置</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-duet-vlm-dual-stage-unified-efficien-2026-sec-32\">三十二 · 尾延迟的压制路径</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-duet-vlm-dual-stage-unified-efficien-2026-sec-33\">三十三 · 压缩比作为调度旋钮：连续批处理下的边界与代价</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-duet-vlm-dual-stage-unified-efficien-2026-sec-34\">三十四 · 切分维度与压缩后序列的耦合</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-duet-vlm-dual-stage-unified-efficien-2026-sec-35\">三十五 · NVLink 5 与 NVSwitch 的带宽账</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-duet-vlm-dual-stage-unified-efficien-2026-sec-36\">三十六 · All-to-All 的尾延迟与压缩比的非线性</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-duet-vlm-dual-stage-unified-efficien-2026-sec-37\">三十七 · NIXL 传输与分离式预填/解码的边界</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-duet-vlm-dual-stage-unified-efficien-2026-sec-38\">三十八 · 通信何时成为瓶颈的判据</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-duet-vlm-dual-stage-unified-efficien-2026-sec-39\">三十九 · 量化与掩码精度对通信路径的隐性影响</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-duet-vlm-dual-stage-unified-efficien-2026-sec-40\">四十 · 压缩比落到并行切分上：DUET-VLM 的通信边界</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-duet-vlm-dual-stage-unified-efficien-2026-sec-41\">四十一 · 精度塌陷：先分清是压缩比越界还是分布漂移</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-duet-vlm-dual-stage-unified-efficien-2026-sec-42\">四十二 · OOM：KV 分配粒度与批估算口径不一致</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-duet-vlm-dual-stage-unified-efficien-2026-sec-43\">四十三 · 批抖动：压缩后长度方差直接放大调度噪声</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-duet-vlm-dual-stage-unified-efficien-2026-sec-44\">四十四 · 尾延迟：显著性计算的算力在预填预算里被低估</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-duet-vlm-dual-stage-unified-efficien-2026-sec-45\">四十五 · 静默降级：掩码数值精度与量化兼容性</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-duet-vlm-dual-stage-unified-efficien-2026-sec-46\">四十六 · 失效边界：压缩比、掩码数值与批调度错配的三类塌陷</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-duet-vlm-dual-stage-unified-efficien-2026-sec-47\">四十七 · 口径先于数字：这份材料能支撑什么结论</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-duet-vlm-dual-stage-unified-efficien-2026-sec-48\">四十八 · 硬件档位：SM100 与 SM103 的差异必须写进表头</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-duet-vlm-dual-stage-unified-efficien-2026-sec-49\">四十九 · batch 与并发：压缩比改变的是批调度粒度</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-duet-vlm-dual-stage-unified-efficien-2026-sec-50\">五十 · 指标定义：TTFT、TPOT、吞吐、显存、功耗各自的口径陷阱</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-duet-vlm-dual-stage-unified-efficien-2026-sec-51\">五十一 · 哪些提升不可比：四类典型错配</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-duet-vlm-dual-stage-unified-efficien-2026-sec-52\">五十二 · 部署侧应补齐的监控口径</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-duet-vlm-dual-stage-unified-efficien-2026-sec-53\">五十三 · 迁移到非 ViT 视觉前端：合并算子的前提会塌</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-duet-vlm-dual-stage-unified-efficien-2026-sec-54\">五十四 · 迁到纯文本或音频：显著性分数的语义锚点不存在</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-duet-vlm-dual-stage-unified-efficien-2026-sec-55\">五十五 · 与量化精度的耦合：NVFP4/FP8 下掩码数值会破一致性</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-duet-vlm-dual-stage-unified-efficien-2026-sec-56\">五十六 · 压缩比与批调度的匹配边界：上限由 SLO 与显存共同夹住</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-duet-vlm-dual-stage-unified-efficien-2026-sec-57\">五十七 · 不适用与需改造的场景清单</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-duet-vlm-dual-stage-unified-efficien-2026-sec-58\">五十八 · 迁移与边界：压缩算子何时失效、何处必须重写</button></li></ol></nav><figure class=\"diagram\" data-fig=\"paper-pipeline\"><svg style=\"max-width:543px;margin:0 auto\" xmlns=\"http://www.w3.org/2000/svg\" viewBox=\"0 0 543.2 352\" preserveAspectRatio=\"xMidYMid meet\" role=\"img\"><rect x=\"58.0\" y=\"12.0\" width=\"461.2\" height=\"44.8\" rx=\"8\" fill=\"#fdf3e3\" stroke=\"#ecd9b8\" stroke-width=\"1.2\"/><circle cx=\"26\" cy=\"34.4\" r=\"12\" fill=\"#1f4e79\"/><text x=\"26.0\" y=\"38.6\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"11.5\" fill=\"#ffffff\" font-weight=\"700\" text-anchor=\"middle\">1</text><text x=\"75.0\" y=\"39.6\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"13.0\" fill=\"#0f1720\" font-weight=\"600\" text-anchor=\"start\">图像或视频帧经预处理切分为 patch，视觉编码器输出全量视觉 tok…</text><line x1=\"82.0\" y1=\"58.8\" x2=\"82.0\" y2=\"75.8\" stroke=\"#d8d3c6\" stroke-width=\"1.4\"/><path d=\"M 77.5 74.8 L 86.5 74.8 L 82.0 82.8 Z\" fill=\"#d8d3c6\"/><rect x=\"58.0\" y=\"82.8\" width=\"461.2\" height=\"44.8\" rx=\"8\" fill=\"#ffffff\" stroke=\"#d8d3c6\" stroke-width=\"1.2\"/><circle cx=\"26\" cy=\"105.3\" r=\"12\" fill=\"#1f4e79\"/><text x=\"26.0\" y=\"109.5\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"11.5\" fill=\"#ffffff\" font-weight=\"700\" text-anchor=\"middle\">2</text><text x=\"75.0\" y=\"110.5\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"13.0\" fill=\"#0f1720\" font-weight=\"600\" text-anchor=\"start\">第一阶段按 token 间相似度做粗粒度合并，降低序列长度并保留空间结…</text><line x1=\"82.0\" y1=\"129.7\" x2=\"82.0\" y2=\"146.7\" stroke=\"#d8d3c6\" stroke-width=\"1.4\"/><path d=\"M 77.5 145.7 L 86.5 145.7 L 82.0 153.7 Z\" fill=\"#d8d3c6\"/><rect x=\"58.0\" y=\"153.7\" width=\"461.2\" height=\"44.8\" rx=\"8\" fill=\"#ffffff\" stroke=\"#d8d3c6\" stroke-width=\"1.2\"/><circle cx=\"26\" cy=\"176.1\" r=\"12\" fill=\"#1f4e79\"/><text x=\"26.0\" y=\"180.3\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"11.5\" fill=\"#ffffff\" font-weight=\"700\" text-anchor=\"middle\">3</text><text x=\"75.0\" y=\"181.3\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"13.0\" fill=\"#0f1720\" font-weight=\"600\" text-anchor=\"start\">合并后 token 经跨模态投影进入第二阶段，按显著性分数剪枝低信息 …</text><line x1=\"82.0\" y1=\"200.5\" x2=\"82.0\" y2=\"217.5\" stroke=\"#d8d3c6\" stroke-width=\"1.4\"/><path d=\"M 77.5 216.5 L 86.5 216.5 L 82.0 224.5 Z\" fill=\"#d8d3c6\"/><rect x=\"58.0\" y=\"224.5\" width=\"461.2\" height=\"44.8\" rx=\"8\" fill=\"#ffffff\" stroke=\"#d8d3c6\" stroke-width=\"1.2\"/><circle cx=\"26\" cy=\"247.0\" r=\"12\" fill=\"#1f4e79\"/><text x=\"26.0\" y=\"251.2\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"11.5\" fill=\"#ffffff\" font-weight=\"700\" text-anchor=\"middle\">4</text><text x=\"75.0\" y=\"252.2\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"13.0\" fill=\"#0f1720\" font-weight=\"600\" text-anchor=\"start\">压缩序列与文本 token 拼接送入解码器，KV cache 按压缩后…</text><line x1=\"82.0\" y1=\"271.4\" x2=\"82.0\" y2=\"288.4\" stroke=\"#d8d3c6\" stroke-width=\"1.4\"/><path d=\"M 77.5 287.4 L 86.5 287.4 L 82.0 295.4 Z\" fill=\"#d8d3c6\"/><rect x=\"58.0\" y=\"295.4\" width=\"461.2\" height=\"44.8\" rx=\"8\" fill=\"#e8f5ec\" stroke=\"#cde9d5\" stroke-width=\"1.2\"/><circle cx=\"26\" cy=\"317.8\" r=\"12\" fill=\"#1f4e79\"/><text x=\"26.0\" y=\"322.0\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"11.5\" fill=\"#ffffff\" font-weight=\"700\" text-anchor=\"middle\">5</text><text x=\"75.0\" y=\"323.0\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"13.0\" fill=\"#0f1720\" font-weight=\"600\" text-anchor=\"start\">解码阶段按压缩后 token 数进行批调度，减少预填算力与显存占用。</text></svg><figcaption><b>流水线</b> · 从输入到输出的数据流；每一步的模块与代价在正文展开。</figcaption></figure>\n<h3 id=\"paper-duet-vlm-dual-stage-unified-efficien-2026-sec-1\">一 · 一个被视觉 token 拖垮的在线服务现场</h3>\n<p>设想一个已经上线的多模态客服系统：用户在网页里上传一张商品图并追问细节，后端是 B200 上的一个 VLM 服务，语言主干按连续批处理跑，视觉编码器按固定分辨率切 patch。工程团队按文本 token 的直觉做了容量规划——每请求 KV 预算按文本长度估算，预填算力按文本 token 数折算。上线后监控立刻出现两处异常：预填阶段的 SM 占用被视觉 token 顶满，而解码阶段的 KV 带宽却远低于预期；并发批大小被压到规划值的一半以下，P99 首 token 延迟随图像分辨率上升呈阶梯式跳变。原因不复杂：视觉编码器输出的 patch 级 token 数随分辨率线性增长，一张高分辨率商品图动辄产生数倍于文本的视觉 token，这些 token 在预填时全部参与注意力计算，在解码时全部占据 KV cache 的物理页。文本侧精心设计的批调度策略，被视觉侧一个与语义无关的维度直接击穿。</p>\n<p>这就是 DUET-VLM 要处理的问题现场：不是“视觉 token 有点多”，而是视觉 token 的数量成为了推理栈里一个不受批调度器控制的、与 SLO 直接冲突的自由变量。在 Blackwell 档位上这个矛盾被放大——SM100 的算力与 HBM 带宽让文本侧的单请求成本降得足够低，低到视觉 token 的预填与 KV 占用成为主导项；tcgen05 与 TMEM 的高利用率反而让“算力被低信息 token 吃掉”这件事在 profiler 里格外刺眼。</p>\n\n<h3 id=\"paper-duet-vlm-dual-stage-unified-efficien-2026-sec-2\">二 · 旧方案的两条路线与它们的结构性缺口</h3>\n<p>论文之前，推理栈处理视觉冗余的主流做法可以归为两条路线，二者都只在一侧生效。</p>\n<p>第一条是推理期剪枝或合并：在视觉编码器输出后、进入语言解码器前，按注意力分数、相似度或语义显著性丢弃一部分 token。这条路线部署成本低，不需要重训，工程上最常见。它的缺口在于训练与部署的分布不一致：模型是在全量 token 序列上训练的，部署时突然只喂给它一个被裁剪过的子集，编码器与投影层的参数从未见过这种分布，精度漂移以不可预测的方式出现。更麻烦的是这种漂移与压缩比强相关——压缩越激进，漂移越大，而漂移的边界没有解析形式，只能靠线上 A/B 试探。</p>\n<p>第二条是训练期正则：在训练时随机丢弃视觉 token 或施加 token 级 dropout，让模型学会在缺失 token 下工作。这条路线保证了训练期见过压缩，但推理期缺少一个与训练一致的、确定性的压缩算子：训练时的随机掩码与部署时的显著性剪枝不是同一个函数，token 选择策略、阈值、保留位置都对不上，分布一致性只解决了一半。</p>\n<p>两条路线的共同缺口是：压缩算子不是一个训练与推理共享的对象。训练侧的可微掩码与部署侧的硬剪枝是两套逻辑，中间靠经验对齐。这在文本侧或许可以容忍，在视觉侧不行——视觉 token 的冗余度与图像内容强相关，同一套阈值在不同图像上产生的压缩比方差很大，训练与推理的偏差会被内容分布进一步放大。</p>\n\n<h3 id=\"paper-duet-vlm-dual-stage-unified-efficien-2026-sec-3\">三 · 代价核算：预填算力、KV 显存与批调度粒度</h3>\n<p>把痛点量化。设视觉 token 数为 $N_v$、文本 token 数为 $N_t$，压缩比为 $\\rho$，则压缩后视觉序列长度为 $\\lfloor \\rho N_v \\rfloor$。预填阶段的自注意力算力随序列长度平方增长，视觉部分贡献的算力份额近似为：</p>\n<div class=\"formula\">$$\\frac{C_v}{C_{\\text{total}}}\\approx\\frac{(N_v+N_t)^2-N_t^2}{(N_v+N_t)^2}=\\frac{N_v^2+2N_vN_t}{(N_v+N_t)^2}$$</div>\n<p>当 $N_v$ 数倍于 $N_t$ 时，这个份额迅速逼近 1——预填算力几乎全部花在视觉 token 上，而其中相当比例是低信息 patch（纯色背景、重复纹理、被遮挡区域）。KV cache 的占用则按 $2\\cdot L\\cdot (N_v+N_t)\\cdot d_h\\cdot b$ 线性增长（$L$ 为层数、$d_h$ 为头维、$b$ 为字节数），视觉部分同样是主导项。这两项叠加的直接后果是批调度器可用的显存预算被压缩，连续批处理能塞进的请求数下降，而下降的幅度与图像分辨率耦合——调度器无法用单一常数刻画单请求成本，只能按最坏情况保守估算，进一步牺牲吞吐。</p>\n<p>具体到一个工程场景：同一台 B200 上，文本-only 请求可以按较大批跑满，一旦混入高分辨率图像请求，调度器要么把整批的批大小调低（牺牲文本请求的吞吐），要么把图像请求隔离到单独队列（牺牲显存利用率与尾延迟）。两种做法都在浪费 Blackwell 的吞吐档位。这就是“非改不可”的工程理由：不是精度问题，是调度粒度问题——单请求成本不可预测，批调度就无法逼近最优。</p>\n\n<h3 id=\"paper-duet-vlm-dual-stage-unified-efficien-2026-sec-4\">四 · 为什么单阶段压缩在 Blackwell 档位上失效</h3>\n<p>单阶段压缩的失效不是精度不够，而是它与推理栈的三个下游组件不匹配。</p>\n<ul>\n<li>与批调度不匹配：单阶段剪枝的压缩比是输入相关的随机变量，调度器按压缩后 token 数估算显存时，估算误差随图像内容波动，保守估算吃掉吞吐。</li>\n<li>与量化精度不匹配：NVFP4/FP8 下，压缩算子的数值行为会变——相似度合并的权重、显著性分数的排序在低精度下可能翻转，导致同一输入在训练（高精度）与部署（低精度）下选出不同的 token 子集，分布一致性被数值精度破坏。</li>\n<li>与 KV 分配粒度不匹配：KV cache 按页分配，压缩后长度若不是页大小的整齐倍数，会产生内部碎片；单阶段压缩的长度分布离散且不可控，碎片率上升。</li>\n</ul>\n<p>论文给出的公式把第二阶段的保留逻辑写清楚：</p>\n<div class=\"formula\">$$\\mathbf{z}_{\\text{out}}=\\operatorname{TopK}_{k}\\left(\\operatorname{Softmax}\\left(\\frac{\\mathbf{Q}\\mathbf{K}^{\\top}}{\\sqrt{d}}\\right)\\right)\\mathbf{V},\\quad k=\\lfloor \\rho N \\rfloor$$</div>\n<p>关键在于 $k$ 由全局压缩比 $\\rho$ 与序列长度 $N$ 共同决定，而不是由单张图像的显著性分布自适应决定——这让压缩后长度成为可预测的量，调度器可以按 $\\lfloor \\rho N \\rfloor$ 估算显存，批大小重新变成可优化变量。单阶段方法缺的正是这个可预测性。</p>\n\n<h3 id=\"paper-duet-vlm-dual-stage-unified-efficien-2026-sec-5\">五 · 两阶段串联如何把压缩变成可调度对象</h3>\n<p>DUET-VLM 的结构把压缩拆成两级，每一级对应推理栈的一个不同瓶颈。第一阶段在视觉编码器输出上按 token 相似度合并近邻 patch，降低序列长度同时保留空间结构——这一级针对的是预填算力，因为合并发生在注意力之前，直接减少参与平方级计算的 token 数。合并算子以可微形式实现，训练时梯度穿过合并矩阵回传至编码器参数，编码器因此学会输出“合并友好”的表示。</p>\n<p>第二阶段在跨模态投影之后按注意力显著性保留 top-k，剪枝掩码参与训练，使编码器适应压缩后分布。这一级针对的是 KV cache 与解码带宽：投影后的 token 已进入语言空间，显著性分数反映的是语言侧的真实需求，保留的 token 与文本查询相关，KV 占用下降的同时精度损失可控。</p>\n<p>两级串联的工程意义在于：粗粒度合并把长度压到一个可控区间，细粒度剪枝在可控区间内做语义选择，压缩后长度由 $\\rho$ 与 $N$ 决定而非由内容自适应决定。调度器拿到的是一个确定性的长度上界，可以据此分配 KV 页、估算预填延迟、决定批大小。训练与推理共享同一算子与阈值策略，意味着部署时的压缩行为就是训练时见过的行为，分布偏移被消除——这是单阶段路线无论如何调参都拿不到的性质。</p>\n\n<h3 id=\"paper-duet-vlm-dual-stage-unified-efficien-2026-sec-6\">六 · 遗留的工程缺口与部署时必须自己补的量</h3>\n<p>论文没有给出压缩比上限、精度损失曲线与失败模式，这意味着部署方必须自己建立压缩比的安全边界。显著性分数计算本身引入额外算力开销——第二阶段要在投影后的序列上算注意力分数并排序，这部分开销与预填收益的对比材料未给出，部署时需与预填延迟预算联合评估：若显著性计算发生在预填关键路径上，压缩收益可能被抵消；若能与预填流水重叠，则收益成立。</p>\n<p>量化兼容性是另一个必须自己验证的点。合并与剪枝算子在 NVFP4/FP8 下的数值行为未给出证据，而可微掩码在低精度下的翻转会直接破坏训练与推理的分布一致性——这正是两阶段方案的核心卖点，一旦被量化破坏，方案退化为单阶段。工程上的判断是：压缩算子应保持在较高精度路径上执行（或在量化前完成），把量化留给压缩后的序列，避免掩码数值精度成为分布一致性的短板。</p>\n<p>监控口径也需补齐：压缩后 token 数与显存占用的对应关系、压缩比的实际分布、批大小与压缩比的联合配置边界，这些在材料里都是空白。一个可操作的起点是把 $\\lfloor \\rho N \\rfloor$ 作为调度器的第一类输入，按压缩后长度而非原始分辨率做容量规划，并在 profiler 里把显著性计算的算力单独记账，与预填节省逐请求对比——只有当这个差值为正且稳定时，压缩才真正转化为吞吐。</p>\n\n<h3 id=\"paper-duet-vlm-dual-stage-unified-efficien-2026-sec-7\">七 · 在线服务的预填墙：单阶段压缩为何在 Blackwell 档位上失效</h3>\n<p>设想一个在线多模态问答服务：单张高分辨率图像切 patch 后视觉 token 随分辨率线性膨胀，视频请求再乘以帧数，文本 token 只占很小一部分。请求到达后，预填阶段要把全量视觉 token 过一遍注意力，KV cache 也按全量长度分配。在固定显存下，批调度器只能按最长请求的 token 数估算占用，于是并发批大小被视觉冗余 token 直接压死，预填延迟与首 token 时间随分辨率抖动，SLO 在高峰期失守。旧方案的主流做法是单阶段压缩：要么在训练侧加 token 剪枝/合并正则，要么在部署侧对视觉 token 做一次性剪枝或池化。问题在于两侧各做各的——训练期梯度看到的 token 分布与部署期剪枝后的分布不一致，压缩比、阈值、显著性口径都对不上，精度漂移在离线评测里不明显，一上高吞吐档位就被批调度和量化放大。</p>\n<p>单阶段方案的系统代价可以写得很直白。设视觉 token 数为 <span class=\"formula\">$$N_v = \\lfloor H/p \\rfloor \\cdot \\lfloor W/p \\rfloor \\cdot F$$</span>（patch 边长 p、帧数 F），单阶段剪枝率 ρ 后序列为 ρN_v，但剪枝掩码若只在推理侧生效，训练期编码器仍按全量 N_v 优化，投影层与解码器的注意力统计也随之偏移。部署侧一次性剪枝的算力开销落在预填路径上：显著性打分本身要算一遍 QK^T，等于在压缩前先付一次全量注意力的代价，压缩收益被前置开销吃掉一部分；而 KV cache 仍按剪枝前的最大长度预留，显存节省有限。更麻烦的是压缩后 token 数与批调度粒度不匹配——调度器按 token 数估算显存，压缩比一变，同一批的显存估算就失真，NVFP4/FP8 量化下掩码与阈值的数值精度还会进一步破坏分布一致性。</p>\n<p>DUET-VLM 的切入点正是把压缩算子做成训练与推理共享的同一套：第一阶段在编码器输出上按相似度合并近邻 token，第二阶段在跨模态投影后按显著性保留 top-k，<span class=\"formula\">$$k=\\lfloor \\rho N \\rfloor$$</span>，两阶段均以可微掩码实现，梯度穿过合并矩阵与剪枝掩码回传至编码器。这样压缩后的序列长度在训练与部署中同分布，KV cache 按压缩长度分配，批调度按压缩后 token 数估算显存，固定显存下并发批大小才真正随 ρ 提升。但这条路径的边界同样清楚：显著性分数计算引入额外算力，材料未给出其与预填收益的定量对比，部署时须与预填延迟预算联合评估；ρ 过高损失关键视觉信息、过低则节省有限，安全压缩上限与精度损失曲线尚未给出；量化后掩码数值精度是否仍维持分布一致性，也需在 NVFP4/FP8 档位上单独验证。换言之，这套方案把“训练-部署分布一致”从口号变成了可配置的压缩比与阈值策略，但压缩比、精度与调度三者的匹配边界，仍是上线前必须补齐的工程判断。</p>\n<h3 id=\"paper-duet-vlm-dual-stage-unified-efficien-2026-sec-8\">八 · 请求长度分布：压缩比把长尾切成什么形状</h3>\n<p>在多模态推理服务里，单请求的 token 长度不是一个标量，而是一个由三部分相加的随机变量：文本提示长度、压缩后的视觉 token 数、以及生成阶段的解码步数。DUET-VLM 的两阶段压缩直接改写了中间那一项——第一阶段按相似度合并把编码器输出的 patch 序列降采样，第二阶段按显著性保留 top-k，最终视觉 token 数由 <span class=\"formula-inline\">k=⌊ρN⌋</span> 决定。这意味着请求长度分布的形状被压缩比 ρ 参数化了：ρ 越小，分布整体左移，长尾被压短；ρ 越大，分布接近未压缩的原始形态，长尾重新变长。</p>\n<p>工程上要盯的不是平均长度，而是分位数。测量口径必须固定为：按请求采样窗口统计 P50/P90/P99 的压缩后视觉 token 数、文本 token 数、总预填 token 数，并同时记录对应的 ρ 取值与输入分辨率/帧数。因为视觉 token 原始数量随分辨率与帧数线性增长，同一 ρ 下高分辨率图像与多帧视频会把 P99 推得很高，而 P50 可能几乎不动。这种“均值稳定、尾部膨胀”的分布正是批调度最难处理的形态：按均值配显存会周期性 OOM，按 P99 配则利用率塌陷。</p>\n<p>一个具体例子：同一批请求中混有单图问答与多帧视频理解，前者压缩后视觉 token 数落在低位，后者即使经过两阶段压缩仍是前者的数倍。若调度器只按滑动平均长度估算 KV 预算，视频请求集中到达时就会出现显存峰值。可核查的做法是把请求按“压缩后视觉 token 数”分桶，统计每桶的到达率与桶内 P99，用分桶直方图而非单一均值驱动批大小决策。</p>\n\n<h3 id=\"paper-duet-vlm-dual-stage-unified-efficien-2026-sec-9\">九 · 并发与批大小：压缩后长度是显存估算的唯一粒度</h3>\n<p>DUET-VLM 的一个直接后果是 KV cache 按压缩后长度分配，解码阶段批调度以压缩后 token 数估算显存。这把批大小的上界从“模型参数量决定的固定值”变成了“随请求长度分布浮动的值”。设单请求压缩后序列长度为 <span class=\"formula-inline\">L<sub>i</sub></span>，每 token 每层 KV 占用为 <span class=\"formula-inline\">2·d<sub>kv</sub>·b</span>（b 为字节数，取决于量化精度），则一批 n 个请求的 KV 显存为：</p>\n<div class=\"formula\">$$M_{\\text{KV}}=\\sum_{i=1}^{n}L_i\\cdot 2\\cdot d_{\\text{kv}}\\cdot b\\cdot N_{\\text{layer}}$$</div>\n<p>这个求和形式说明批大小不是独立变量：压缩比 ρ 降低 <span class=\"formula-inline\">L<sub>i</sub></span>，在固定显存预算下 n 可以增大，吞吐上升；但 ρ 同时影响精度，压缩过高会丢掉关键视觉信息。于是并发能力与压缩比构成一条权衡曲线，部署时必须把 ρ 当作调度参数而非静态超参。</p>\n<p>测量口径：在固定显存上限下，扫描 ρ 与目标并发，记录实际达成的批大小、每批的预填 token 总数、KV 显存占用峰值、以及单位时间完成的请求数。关键是要区分“名义批大小”与“有效批大小”——后者按压缩后 token 数加权，因为长短请求混批时，短请求占的槽位多但算力贡献少。Blackwell 档位上的高吞吐依赖大 batch 填满 SM，若批内长度方差过大，tcgen05 的 MMA 利用率会被最短序列拖住，这一点必须在测量中体现为批内长度方差与预填算力利用率的联合指标。</p>\n<p>反过来，方案也限制负载：两阶段压缩的显著性分数计算本身要消耗算力，这部分开销发生在预填之前，属于固定成本。当请求很短（低分辨率单图）时，压缩收益有限而显著性计算开销不变，单位请求的算力反而上升。因此负载形态决定了压缩是否划算——短请求占比高的负载，ρ 不宜过低。</p>\n\n<h3 id=\"paper-duet-vlm-dual-stage-unified-efficien-2026-sec-10\">十 · SLO 与长尾：预填延迟的两个来源</h3>\n<p>SLO 约束下，预填延迟随压缩后序列长度下降，这是 DUET-VLM 的预期收益。但预填延迟并不只由长度决定，它由两部分构成：视觉编码器与两阶段压缩的前置开销，以及解码器预填的注意力计算。前者与压缩比无关（甚至随显著性计算略微上升），后者随 <span class=\"formula-inline\">k=⌊ρN⌋</span> 线性下降。设前置开销为 <span class=\"formula-inline\">T<sub>pre</sub></span>，预填计算为 <span class=\"formula-inline\">c·k</span>，则：</p>\n<div class=\"formula\">$$T_{\\text{TTFT}}=T_{\\text{pre}}(\\rho)+c\\cdot\\lfloor\\rho N\\rfloor+T_{\\text{queue}}$$</div>\n<p>其中 <span class=\"formula-inline\">T<sub>queue</sub></span> 是排队时间，由并发与批调度决定。长尾请求的 TTFT 往往不是被自身长度拖垮，而是被同批中更长的请求拖住——连续批处理中一个长请求会占住一个槽位直到其预填完成。测量口径必须把 TTFT 拆成排队、前置、预填三段分别统计 P50/P99，否则无法判断压缩到底改善了哪一段。若 P99 的 TTFT 主要由 <span class=\"formula-inline\">T<sub>queue</sub></span> 贡献，那么降低 ρ 的收益会被排队噪声淹没。</p>\n<p>具体例子：视频请求的帧数多，前置开销中的编码器计算占比高，即使 ρ 压到很低，TTFT 的下界仍由编码器决定。此时对视频请求单独设更宽松的 SLO、或把它路由到专用副本，比全局调低 ρ 更有效。这体现了负载塑造方案：SLO 分层要求调度器识别请求类型，而不是对所有请求用同一压缩比。</p>\n\n<h3 id=\"paper-duet-vlm-dual-stage-unified-efficien-2026-sec-11\">十一 · 负载如何反向约束方案设计</h3>\n<p>前面的分析都是“方案影响负载指标”，但工程上更关键的是反向约束。第一，压缩比必须与批调度联合配置，材料明确指出压缩后 token 数与批调度的匹配边界未给出。若调度器按未压缩长度预留显存，压缩带来的显存节省无法转化为并发提升；若按压缩后长度预留但 ρ 在运行时动态变化，显存估算会失准。可核查的设计是把 ρ 固定为调度器可见的配置项，按 ρ 分副本部署，而不是在单副本内混用多个 ρ。</p>\n<p>第二，量化精度与压缩算子耦合。NVFP4/FP8 下合并矩阵与剪枝掩码的数值精度影响待验证，而训练与推理共享算子依赖可微掩码——量化后掩码数值精度可能破坏分布一致性。这意味着负载若要求低精度高吞吐，压缩比的安全上限会被进一步压低。测量口径应包含：在目标量化档位下，压缩后 token 数与全精度路径的偏差、以及精度指标随 ρ 的变化曲线，缺此曲线就无法确定安全压缩上限。</p>\n<p>第三，长尾请求的失败模式是压缩过高丢失关键视觉信息。材料未给出失败模式与监控口径，部署时需补齐压缩后 token 数与显存占用的监控指标。可操作的做法是记录每请求的 ρ、压缩前后 token 数、显著性分数的分布熵，当熵异常低（说明剪枝把大部分 token 判为低信息）时触发告警，因为这往往对应需要细粒度视觉信息的请求。</p>\n\n<h3 id=\"paper-duet-vlm-dual-stage-unified-efficien-2026-sec-12\">十二 · 可核查的测量口径清单</h3>\n<p>把上述讨论收敛成一组可复现的测量项，避免用定性描述替代证据：</p>\n<table class=\"mini\"><thead><tr><th>维度</th><th>测量项</th><th>用途</th></tr></thead><tbody>\n<tr><td>长度分布</td><td>压缩前后视觉 token 数、文本 token 数、总预填长度的 P50/P90/P99，按 ρ 与分辨率/帧数分组</td><td>判断长尾形状与分桶调度必要性</td></tr>\n<tr><td>并发</td><td>固定显存下的有效批大小、批内长度方差、预填算力利用率</td><td>验证 ρ 是否真正转化为并发</td></tr>\n<tr><td>SLO</td><td>TTFT 拆分为排队/前置/预填三段的分位数</td><td>定位压缩改善的是哪一段</td></tr>\n<tr><td>显存</td><td>KV 显存峰值、压缩后长度与预留长度的偏差</td><td>检查调度器估算是否失准</td></tr>\n<tr><td>精度</td><td>目标量化档位下压缩路径与全精度路径的输出偏差、ρ 扫描曲线</td><td>确定安全压缩上限</td></tr>\n<tr><td>开销</td><td>显著性分数计算的算力与延迟、单位请求压缩收益比</td><td>判断短请求负载下压缩是否划算</td></tr>\n</tbody></table>\n<p>这张表的每一行都对应一个可被证伪的判断。例如“压缩提高并发”只有在有效批大小随 ρ 单调上升且批内方差可控时才成立；“压缩降低 TTFT”只有在预填段占比显著时才成立。材料未给出数据集、基线数字与消融结果，因此这些测量项在本文中只作为口径定义，不作为结论。</p>\n<p>最后落在工程判断上：DUET-VLM 的压缩算子把请求长度分布、批大小、SLO 三者绑在同一条参数 ρ 上，任何部署都必须把 ρ 当作调度契约的一部分——它同时决定显存估算粒度、预填延迟下界和精度边界。在补齐压缩比与精度损失的定量边界之前，安全的做法是按请求类型分桶、按桶设 ρ、按桶统计上述分位数，而不是用一个全局压缩比覆盖全部负载形态。</p>\n\n<h3 id=\"paper-duet-vlm-dual-stage-unified-efficien-2026-sec-13\">十三 · 压缩比作为负载整形旋钮：边界、失效与可核查口径</h3>\n<p>DUET-VLM 的压缩比 ρ 不只是精度参数，它是把请求负载形态直接改写的一根旋钮。单请求压缩后视觉序列长度为 k=⌊ρN⌋，于是请求总长 L=L_text+k，KV 占用与预填 FLOPs 都随 L 线性缩放。这意味着压缩比同时作用在三个层面：单请求延迟（预填随 L 下降）、并发批大小（固定显存下可容纳的请求数约按 1/L 增长）、以及长尾分布的形状——原本因高分辨率图像而超长的那一小撮请求被压短，尾部的显存尖峰被削平，但削平的程度完全取决于 ρ 的取值，而非请求本身。工程上必须把 ρ 与批调度器联合配置：调度器按压缩后 token 数估算显存，若 ρ 在运行期动态变化（例如按图像内容自适应），估算口径就会失配，出现预留显存与实际占用不一致的排队抖动。</p>\n<p>失效条件集中在两端。ρ 过高时，第二阶段 TopK 剪枝丢弃的 token 可能承载关键视觉信息，而材料未给出精度损失曲线，部署方无法确定安全上限；ρ 过低时节省有限，KV 显存与预填算力几乎未变，两阶段算子的开销却照付。更隐蔽的代价是显著性分数计算本身：第二阶段要对投影后序列做注意力打分再排序，这部分算力与 N 成正比，若 ρ 接近 1，收益被开销抵消。可用一个粗口径判断：设单请求预填节省为 (1−ρ)·c_pre·N，显著性开销为 c_sal·N，则净收益为正需 (1−ρ)·c_pre > c_sal，其中 c_pre、c_sal 需在目标 Blackwell 档位上实测，材料未给出二者数值，因此该不等式只能作为部署前的测量清单而非结论。</p>\n<p>可核查的测量口径应至少覆盖四项，缺一不可：其一，按分辨率与帧数分桶统计压缩前 N 与压缩后 k 的分布，确认尾部请求的实际压缩率是否与配置的 ρ 一致（自适应策略下二者会偏离）；其二，记录每请求 KV 分配字节数与调度器估算值的偏差，这是批大小失配的直接指标；其三，单独计时第二阶段显著性打分，与预填总时长对比，判断开销占比；其四，在 NVFP4/FP8 档位上复测合并矩阵与剪枝掩码的数值行为——材料明确指出量化与压缩算子的兼容性未验证，可微掩码在低精度下若发生舍入偏移，训练与推理共享的阈值策略就会被破坏，分布一致性这一核心卖点随之失效。下表给出这四项口径与对应风险。</p>\n<table class=\"mini\"><thead><tr><th>口径</th><th>观测量</th><th>失配风险</th></tr></thead><tbody><tr><td>压缩率分布</td><td>分桶 N 与 k</td><td>尾部未按 ρ 收缩，长尾尖峰仍在</td></tr><tr><td>显存估算偏差</td><td>实际 KV 字节 vs 调度估算</td><td>批大小抖动、排队延迟上升</td></tr><tr><td>显著性开销占比</td><td>打分时长 / 预填时长</td><td>ρ 偏高时净收益转负</td></tr><tr><td>低精度掩码一致性</td><td>FP8/NVFP4 下 top-k 集合差异</td><td>训练推理分布偏移，精度漂移</td></tr></tbody></table>\n<p>反向约束同样成立：负载形态会反过来限制方案的可选空间。若线上请求以短文本加中等分辨率图像为主，N 本就不大，两阶段压缩的固定开销占比上升，ρ 的下限被抬高；若长尾由视频帧数驱动，N 随帧数线性增长，压缩收益显著，但帧间 token 的相似度合并可能抹掉运动细节，此时第一阶段的空间结构保留假设不再成立，需要按模态分流配置阈值。因此 DUET-VLM 的部署判断不是选一个全局 ρ，而是按请求桶分别标定 ρ 与阈值，并把显著性开销纳入预填延迟预算后再决定是否启用第二阶段——在材料未给出定量边界的前提下，这是唯一可执行的工程路径。</p>\n<h3 id=\"paper-duet-vlm-dual-stage-unified-efficien-2026-sec-14\">十四 · 两阶段压缩算子的 kernel 形态与数值路径</h3>\n<p>DUET-VLM 的两阶段压缩在算子层面是两种截然不同的 kernel：第一阶段是相似度合并，本质上是小规模成对点积加加权求和；第二阶段是显著性 top-k 选择，本质上是打分、排序、按掩码聚合。两者都要在视觉编码器输出与跨模态投影之后紧接执行，因此它们的数值路径直接决定了后续语言解码器预填的输入分布。合并算子的计算可以写成对近邻集合 $\\mathcal{N}(i)$ 的加权平均：</p>\n<div class=\"formula\">$$\\mathbf{h}'_i=\\sum_{j\\in\\mathcal{N}(i)} w_{ij}\\,\\mathbf{h}_j,\\quad w_{ij}=\\frac{\\exp(\\mathbf{h}_i^\\top\\mathbf{h}_j/\\tau)}{\\sum_{m\\in\\mathcal{N}(i)}\\exp(\\mathbf{h}_i^\\top\\mathbf{h}_m/\\tau)}$$</div>\n<p>这里 $\\mathbf{h}_i$ 是 patch 级 token 的隐状态，$\\tau$ 是温度，$w_{ij}$ 是合并权重。工程上这个式子的代价不在乘加量，而在它必须保持可微：训练时 $w_{ij}$ 要参与梯度回传，推理时又要退化为一次固定权重的归约。若用 FP16 存 $\\mathbf{h}$、FP32 累加相似度，点积在 $d=1024$ 量级上仍会因舍入产生排序翻转，近邻集合的边界 token 会在不同 batch 间跳变，导致同一图像在训练与推理得到不同的合并结果——这正是分布偏移的一个隐蔽来源。Blackwell 的第五代 Tensor Core 对 FP16/BF16 的乘加有原生支持，但 softmax 归约与 top-k 比较仍在 CUDA core 上完成，因此合并 kernel 的实际瓶颈往往是归约与写回，而不是 MMA 本身。</p>\n<p>第二阶段剪枝的公式在材料中给出：</p>\n<div class=\"formula\">$$\\mathbf{z}_{\\text{out}}=\\operatorname{TopK}_{k}\\left(\\operatorname{Softmax}\\left(\\frac{\\mathbf{Q}\\mathbf{K}^{\\top}}{\\sqrt{d}}\\right)\\right)\\mathbf{V},\\quad k=\\lfloor \\rho N \\rfloor$$</div>\n<p>逐项看：$\\mathbf{Q}\\mathbf{K}^\\top/\\sqrt{d}$ 是缩放点积打分，$\\sqrt{d}$ 的缩放使打分方差与 $d$ 无关，避免 softmax 在长序列上饱和；Softmax 把打分变成显著性分布；$\\operatorname{TopK}_k$ 按 $\\rho N$ 截断，$\\rho$ 是压缩比、$N$ 是合并后的序列长度；最后用保留位置的 $\\mathbf{V}$ 聚合。注意这里的 top-k 是在 softmax 之后取，等价于取概率质量最大的 $k$ 个 token，而不是取打分最大的 $k$ 个——两者在数值上接近但在低精度下不同：FP8 下 softmax 分母的累加误差会改变排序，使被剪掉的 token 集合在训练与推理间不一致。这就是为什么剪枝掩码必须与打分共用同一精度路径。</p>\n\n<h3 id=\"paper-duet-vlm-dual-stage-unified-efficien-2026-sec-15\">十五 · 数据类型选择：FP16、BF16、FP8 与 NVFP4 的分工</h3>\n<p>在 Blackwell 上，这四种精度不是互斥选项，而是按算子位置分工。合并算子的相似度点积适合 BF16：BF16 的 8 位指数与 FP32 同宽，能容纳视觉 token 隐状态中较大的动态范围，避免 FP16 在 $|\\mathbf{h}|&gt;65504$ 时的溢出；但 BF16 只有 7 位尾数，点积的相对误差约 $2^{-8}$，在近邻边界上足以翻转 $w_{ij}$ 的排序。因此工程做法是：BF16 存激活、FP32 累加点积、softmax 在 FP32 中完成后再降回 BF16 写回。这一步的代价是寄存器压力——FP32 累加使每个线程的寄存器占用翻倍，在 tcgen05 的 MMA 流水里会压缩可并行的 tile 数，直接体现为合并 kernel 的占用率下降。</p>\n<p>第二阶段的打分与 top-k 更适合 FP8。打分矩阵 $\\mathbf{Q}\\mathbf{K}^\\top$ 的元素是标量内积，FP8（E4M3）的 3 位尾数给出约 $2^{-4}$ 的相对精度，对显著性排序足够，因为 top-k 只关心相对次序而非绝对值。真正敏感的是 $\\mathbf{V}$ 的聚合：被保留 token 的加权和若在 FP8 中累加，$k$ 较大时误差随 $\\sqrt{k}$ 增长，会污染送入解码器的视觉特征。所以聚合应在 FP32 或至少 BF16 中累加，FP8 只用于打分。NVFP4 的定位更窄：它适合权重侧的块量化（每 16 或 32 个元素共享一个缩放因子），在合并矩阵这类静态权重上可把带宽压到 FP8 的一半，但激活侧的相似度计算不适合 NVFP4，因为 2 位尾数无法区分近邻 token 的细微差异，合并结果会退化为近似均匀平均，空间结构信息丢失。</p>\n<table class=\"mini\"><thead><tr><th>算子位置</th><th>存储精度</th><th>累加精度</th><th>主要风险</th></tr></thead><tbody><tr><td>相似度点积</td><td>BF16</td><td>FP32</td><td>近邻排序翻转</td></tr><tr><td>合并权重 softmax</td><td>FP32 中间</td><td>FP32</td><td>寄存器压力、占用率</td></tr><tr><td>显著性打分</td><td>FP8 E4M3</td><td>FP32</td><td>softmax 分母误差改变 top-k 集合</td></tr><tr><td>保留 token 聚合</td><td>FP8 输入</td><td>BF16/FP32</td><td>误差随 $\\sqrt{k}$ 累积</td></tr><tr><td>合并矩阵权重</td><td>NVFP4 块量化</td><td>FP32</td><td>块缩放因子边界不连续</td></tr></tbody></table>\n<p>一个具体例子：一段 1080p 视频抽 8 帧，每帧 patch 化后视觉 token 数为数千量级，第一阶段合并把序列压到原来的几分之一，第二阶段再按 $\\rho$ 截断。若打分用 FP8 而聚合用 FP8，被保留 token 的特征在送入解码器前已经带上累加误差，解码器预填的 KV 就建立在有偏的视觉表示上；反之若打分用 BF16，打分矩阵的显存与带宽翻倍，在固定显存下并发批大小下降。这就是精度选择与批调度之间的直接耦合：精度不是孤立指标，它通过 kernel 占用率与显存占用传导到吞吐。</p>\n\n<h3 id=\"paper-duet-vlm-dual-stage-unified-efficien-2026-sec-16\">十六 · Blackwell 特性：tcgen05、TMEM 与 2-SM MMA 对压缩算子的意义</h3>\n<p>tcgen05 是 Blackwell 上第五代 Tensor Core 的指令族，其关键变化是把 MMA 的累加器从寄存器文件搬到 Tensor Memory（TMEM）。对 DUET-VLM 的合并算子，这意味着相似度矩阵 $\\mathbf{H}\\mathbf{H}^\\top$ 的累加可以留在 TMEM 中，不必每个 tile 都写回寄存器再读出，减少了寄存器压力与数据搬运。TMEM 的容量按 CTA 分配，一个 CTA 能容纳的累加 tile 有限，因此合并 kernel 的 tile 划分必须与 TMEM 容量对齐：tile 太大则放不下，tile 太小则 MMA 利用率低。这是压缩算子在高吞吐档位上的第一个结构性约束。</p>\n<p>2-SM MMA 让两个 SM 协作完成一次更大的 MMA，等效于把单个 MMA 的 N 维或 M 维翻倍。对第二阶段剪枝，打分矩阵 $\\mathbf{Q}\\mathbf{K}^\\top$ 的规模随 $N$ 线性增长，2-SM MMA 能把打分 tile 做大，减少 top-k 前的中间结果写回次数。但 top-k 本身不是 MMA 能加速的部分：它需要在打分矩阵上做全局比较，跨 tile 的归并必须经过共享内存或分布式共享内存，2-SM 协作反而增加了跨 SM 同步的代价。因此剪枝 kernel 的收益边界在于打分占比与 top-k 占比的相对大小——打分越长，2-SM MMA 越值得；序列越短，同步开销越可能吃掉收益。</p>\n<p>代价体现在三个维度。延迟上，tcgen05 的 MMA 流水需要预取与双缓冲，合并 kernel 的启动开销在短序列上不可忽略；吞吐上，TMEM 容量限制了同时驻留的累加 tile 数，压缩比越高、序列越短，MMA 的固定开销占比越大；功耗上，FP8 与 NVFP4 的 MMA 能效高于 BF16，但 softmax 与 top-k 仍在 CUDA core 上以 FP32 运行，这部分功耗不随精度降低而下降，成为压缩算子功耗的下限。一个工程判断是：当压缩后序列长度落到数百 token 量级时，两阶段算子的固定开销可能已经与预填收益同量级，此时应把合并与剪枝融合进同一个 kernel，用一次 TMEM 驻留完成打分、合并与截断，避免两次 kernel 启动与两次中间结果写回。</p>\n\n<h3 id=\"paper-duet-vlm-dual-stage-unified-efficien-2026-sec-17\">十七 · 累加精度与误差传播：从合并到 KV cache</h3>\n<p>压缩算子的数值误差不会停在算子内部，它会沿两条路径传播。第一条是合并权重的误差：$w_{ij}$ 的舍入误差使合并后的 token 偏离真实加权平均，这个偏差进入投影层后被放大为跨模态对齐误差，最终改变解码器对视觉内容的注意力分布。第二条是 top-k 集合的误差：打分排序的翻转使被剪掉的 token 集合在不同精度下不同，训练时掩码与推理时掩码不一致，编码器学到的压缩后分布与部署时实际分布错位。两条路径的共同后果是 KV cache 中视觉部分的键值向量带有系统性偏差，而 KV cache 按压缩后长度分配，偏差不会因长度缩短而消失。</p>\n<p>误差的量级可以用一个简化模型估计。设合并集合大小为 $m$，每个元素的相对误差为 $\\epsilon$，则合并结果的相对误差约为 $\\epsilon/\\sqrt{m}$（误差独立时）；但若 $w_{ij}$ 本身有偏，误差不随 $m$ 减小，反而因权重归一化的舍入而累积。对 top-k 聚合，设保留 $k$ 个 token、每个 $\\mathbf{V}$ 元素相对误差 $\\epsilon_V$，聚合结果的误差约 $\\epsilon_V\\sqrt{k}$，因为加权和的方差随项数增长。这两个式子给出相反的工程指向：合并要控制权重精度（用 FP32 softmax），剪枝要控制聚合精度（用 BF16/FP32 累加），而打分本身可以用低精度。把这三条分开配置，才能在压缩比与精度之间找到可验证的边界。</p>\n<p>具体例子：若第一阶段用 BF16 存激活、FP32 算 softmax、BF16 写回，第二阶段用 FP8 打分、FP32 累加聚合，则合并误差主要来自 BF16 写回（约 $2^{-8}$ 相对误差），剪枝误差主要来自打分排序翻转而非聚合。此时若把压缩比 $\\rho$ 调高，$k$ 变小，聚合误差随 $\\sqrt{k}$ 下降，但打分排序在更短的候选集上更容易被低精度翻转，掩码不一致的风险上升。这说明压缩比与精度不是独立旋钮：提高压缩比会同时降低聚合误差敏感度、提高排序敏感度，部署时必须联合标定。</p>\n\n<h3 id=\"paper-duet-vlm-dual-stage-unified-efficien-2026-sec-18\">十八 · 量化与压缩算子的兼容性缺口</h3>\n<p>材料明确指出未给出量化方案与压缩算子的兼容性证据，NVFP4/FP8 下合并与剪枝算子的数值精度影响待验证。这个缺口在工程上有具体形态。可微掩码在训练时是浮点张量，量化后掩码若被压成低精度，其梯度近似会破坏“训练与推理共享同一算子”的前提：训练时掩码是软的，推理时掩码是硬的（top-k 是离散选择），两者之间的差距靠训练期的软掩码来弥合；一旦掩码在量化中被截断，软硬之间的过渡带消失，编码器适应的分布与部署分布重新错位。</p>\n<p>另一个形态是块量化的边界效应。NVFP4 的块缩放因子按固定块大小共享，若合并矩阵的权重在块边界处跨越不同的缩放因子，相邻块的量化步长不连续，合并结果的相邻 token 会出现阶梯状偏差。这种偏差在空间结构上表现为块状伪影，恰好破坏第一阶段“保留空间结构”的目标。工程上的缓解是把合并矩阵按 token 邻接关系重排后再块量化，使同一块的权重来自空间上相近的近邻，缩放因子在块内更一致；代价是重排带来一次额外的数据搬运，在带宽受限的预填阶段需要与合并 kernel 融合。</p>\n<p>兼容性缺口的系统代价是双重的：一方面，量化带来的带宽节省可能被掩码精度损失导致的精度漂移抵消，部署方无法从压缩比单独推算端到端收益；另一方面，压缩后 token 数与批调度的匹配边界未给出，量化后的 kernel 占用率变化会改变单请求预填延迟，进而改变批调度器估算显存与并发批大小的口径。在 Blackwell 高吞吐档位上，这两者叠加意味着压缩、量化、调度三个旋钮必须一起标定，而不能各自独立调优。</p>\n\n<h3 id=\"paper-duet-vlm-dual-stage-unified-efficien-2026-sec-19\">十九 · 精度路径的工程判断</h3>\n<p>把上述机制收敛成一条可执行的精度路径：合并算子用 BF16 激活、FP32 相似度与 softmax、BF16 写回，合并矩阵权重可用 NVFP4 块量化但需按空间邻接重排；剪枝算子用 FP8 打分、FP32 top-k 比较、BF16 或 FP32 聚合；两阶段共享同一套阈值与掩码生成逻辑，掩码在量化前后保持同一比较语义。这条路径的代价是 FP32 中间量带来的寄存器与 TMEM 压力，收益是训练与推理的 token 分布一致性不被低精度破坏。</p>\n<p>判断是否值得走这条路径，取决于压缩后序列长度与预填延迟预算的相对关系。若压缩后序列仍在千 token 量级，MMA 与归约的固定开销占比低，精度路径的额外 FP32 累加可以被吞吐摊薄；若压缩后序列落到数百 token，固定开销成为主导，此时应优先融合两阶段 kernel、减少中间写回，而不是继续压低精度。材料未给出压缩比上限与精度损失曲线，因此这条路径的边界只能在部署中用压缩后 token 数与显存占用的监控口径来标定——而这正是当前材料留下的、必须由工程侧补齐的定量证据。</p>\n<h3 id=\"paper-duet-vlm-dual-stage-unified-efficien-2026-sec-20\">二十 · 从“全量视觉 token”出发的显存账本</h3>\n<p>DUET-VLM 的显存账本必须从视觉编码器吐出全量 patch token 的那一刻开始记。设图像切分为 N<sub>v</sub> 个 patch token，文本侧提示长度为 N<sub>t</sub>，则未压缩时预填阶段的 KV 条目数按 N<sub>v</sub>+N<sub>t</sub> 计。压缩后序列长度为 N<sub>c</sub>=N<sub>t</sub>+⌊ρN<sub>v</sub>⌋（ρ 为第二阶段保留比），KV cache 分配粒度随之改变。账本分三栏：权重、激活、KV。权重是静态的，与压缩比无关；激活在预填峰值时由中间张量决定；KV 是唯一随 ρ 线性缩放的项，也是批调度真正卡住的地方。工程上先把三栏写成可复算形式，再谈压缩收益，否则“压缩后显存下降”只是一句无法验收的话。</p>\n<div class=\"formula\">$$M_{\\text{kv}}=2\\cdot L\\cdot H_{\\text{kv}}\\cdot d_{\\text{head}}\\cdot s\\cdot B\\cdot(N_t+\\lfloor\\rho N_v\\rfloor)$$</div>\n<p>其中 L 为解码器层数，H<sub>kv</sub> 为 KV 头数（GQA 下小于注意力头数），d<sub>head</sub> 为头维，s 为每元素字节数（FP8 为 1，BF16 为 2），B 为并发批大小。系数 2 来自 K 与 V 两份。这个式子的关键含义是：ρ 只作用于视觉项，文本项 N<sub>t</sub> 不受压缩影响，因此当 N<sub>t</sub> 与 ρN<sub>v</sub> 同量级时，压缩带来的 KV 节省会被文本项稀释。DUET-VLM 的收益边界由此确定——高分辨率、多帧、短提示的请求收益最大；长提示、低分辨率请求收益有限。</p>\n<p>举一个可复算的例子：设 L=80、H<sub>kv</sub>=8、d<sub>head</sub>=128、s=1（FP8 KV）、B=32、N<sub>t</sub>=512、N<sub>v</sub>=4096。未压缩时每请求 KV 为 2×80×8×128×1×(512+4096)=2×80×1024×4608≈7.55×10<sup>8</sup> 字节，约 720 MiB；B=32 时约 23 GiB。若 ρ=0.25，视觉项降到 1024，每请求约 2×80×1024×1536≈2.52×10<sup>8</sup> 字节，约 240 MiB，32 并发约 7.7 GiB。同一张卡上并发批大小可从受 KV 限制的档位抬升约三倍。这个算例只用给定结构参数与自设的层数/头数，不引用任何实验数字，读者可替换为自己的模型配置复算。</p>\n\n<h3 id=\"paper-duet-vlm-dual-stage-unified-efficien-2026-sec-21\">二十一 · 分页与压缩后长度的对齐</h3>\n<p>KV cache 分页（PagedAttention 类机制）把 KV 切成固定大小的 block，按需分配、按 block 表索引。压缩比 ρ 与 block 大小的对齐关系直接决定碎片率。设 block 容纳 b 个 token，则单请求视觉部分占用 block 数为 ⌈ρN<sub>v</sub>/b⌉，浪费上界为 (b−1)/b 个 block 的尾部空间。ρN<sub>v</sub> 若不是 b 的整数倍，每个请求尾部都有空洞；B 越大，空洞总量越可观。DUET-VLM 的压缩后长度由 ρ 与 N<sub>v</sub> 共同决定，而 N<sub>v</sub> 随分辨率与帧数变化，因此 ρ 不宜取“整齐”的固定值，而应按 block 边界向上取整后再分配，避免跨请求的碎片累积。</p>\n<p>代价体现在两个方向。碎片抬高显存占用，降低可并发批大小；而分页表的间接寻址在解码阶段每次 attention 都要读 block 表，压缩后序列变短会减少 block 数、降低表遍历开销，但若 block 太小则表项密度上升，间接寻址的带宽占比反而变大。工程判断是：压缩比高的部署档位应适当增大 block 尺寸，用少量尾部浪费换取更少的表项与更低的寻址开销；压缩比低的档位则保持小块以压低碎片。这一取舍与预填/解码的分离式部署耦合——预填侧关心 block 分配速度，解码侧关心 block 读取带宽。</p>\n\n<h3 id=\"paper-duet-vlm-dual-stage-unified-efficien-2026-sec-22\">二十二 · 带宽瓶颈：预填算力与解码 KV 读</h3>\n<p>压缩对两个阶段的收益机制不同。预填阶段是算力主导：注意力矩阵规模随序列长度平方增长，压缩把 N<sub>v</sub> 降到 ρN<sub>v</sub>，预填 FLOPs 近似按 (N<sub>t</sub>+ρN<sub>v</sub>)<sup>2</sup> 缩放，收益显著。解码阶段是带宽主导：每生成一个 token，需要把整条 KV cache 从 HBM 读一遍，读量为 M<sub>kv</sub>/B 的单请求份额。压缩把视觉 KV 读量按 ρ 缩减，解码每步的 HBM 流量下降，token 间延迟（TPOT）随之改善。Blackwell 的 HBM3e 带宽很高，但解码阶段的实际瓶颈常在 KV 读取的有效带宽而非峰值带宽——分页带来的非连续访问、GQA 下的头共享、以及 FP8 KV 的解量化开销都会吃掉一部分。</p>\n<div class=\"formula\">$$T_{\\text{decode per token}}\\approx \\frac{2\\cdot L\\cdot H_{\\text{kv}}\\cdot d_{\\text{head}}\\cdot s\\cdot(N_t+\\lfloor\\rho N_v\\rfloor)}{BW_{\\text{eff}}}$$</div>\n<p>这个式子说明：ρ 对 TPOT 的改善是线性的，但 N<sub>t</sub> 是分母中的常数项，长提示场景下压缩的边际收益递减。另一个常被忽略的代价是第二阶段显著性分数计算的额外算力——它发生在预填路径上，需要算注意力分数再 TopK，属于“为了省 KV 而多算一步”。材料未给出该开销与预填收益的定量对比，部署时必须把它计入预填延迟预算：若显著性计算本身占预填时间的比例接近压缩节省的比例，净收益会被抵消。工程上可把显著性分数复用预填注意力的中间结果，避免二次前向。</p>\n\n<h3 id=\"paper-duet-vlm-dual-stage-unified-efficien-2026-sec-23\">二十三 · 复用与卸载：压缩后 KV 的层级放置</h3>\n<p>压缩后的 KV 有两个可复用面。其一是前缀复用：同一图像或同一视频帧序列在多轮对话中被反复引用，压缩后的视觉 KV 可跨请求缓存，命中时跳过视觉编码与两阶段压缩，直接拼接到文本 KV 前。复用粒度应按压缩后长度对齐 block，否则命中后仍需重排。其二是层级卸载：把冷请求的 KV 从 HBM 卸到主机内存或远端存储，按需回迁。压缩比在这里是杠杆——ρ 越低，单请求 KV 越小，同样容量的主机内存能驻留更多请求，卸载/回迁的传输量也按 ρ 缩减。代价是回迁延迟进入 TPOT 的关键路径，卸载策略必须与 SLO 绑定：只卸载预计空闲时间超过回迁代价的请求。</p>\n<p>复用与卸载共同改变批调度的显存估算口径。DUET-VLM 的调度按压缩后 token 数估算显存，但复用命中率与卸载驻留率是动态量，静态按 ρN<sub>v</sub> 估算会高估或低估可用批大小。工程做法是把 KV 账本拆成“活跃 KV”与“可回收 KV”两本账，调度器只对活跃部分做硬约束，可回收部分作为弹性缓冲。这样压缩比、分页 block、复用命中率三者才能在同一个预算式里联合配置，而不是各自拍脑袋。</p>\n\n<h3 id=\"paper-duet-vlm-dual-stage-unified-efficien-2026-sec-24\">二十四 · HBM3e 容量怎么算与预算模板</h3>\n<p>单卡可用显存 = HBM 容量 − 权重 − 激活峰值 − 框架与通信缓冲。权重按参数量×每参数字节估算，FP8 与 NVFP4 下分别按 1 字节与 0.5 字节计（含 scale 开销需另留余量）；激活峰值出现在预填最长序列处，与压缩后长度和批内最大序列相关；通信缓冲在张量并行与专家并行下不可忽略。剩余部分才是 KV 预算，除以单请求 KV 即得并发上限。GB200 NVL72 这类机柜级部署把容量问题转化为跨卡聚合问题：单卡 HBM 有限，但 NVLink 域内的 KV 可分片放置，压缩比降低的是整个域内的 KV 总量，从而抬高域级并发。</p>\n<table class=\"mini\"><thead><tr><th>账本项</th><th>决定因素</th><th>与 ρ 的关系</th><th>工程动作</th></tr></thead><tbody><tr><td>权重</td><td>参数量、量化格式</td><td>无关</td><td>FP8/NVFP4 量化，预留 scale 余量</td></tr><tr><td>激活峰值</td><td>预填最长序列、批内最大长度</td><td>随 (N<sub>t</sub>+ρN<sub>v</sub>) 缩放</td><td>限制单批最长序列，分块预填</td></tr><tr><td>KV 活跃</td><td>并发批、压缩后长度、KV 精度</td><td>线性于 ρ</td><td>按 block 对齐分配，FP8 KV</td></tr><tr><td>KV 可回收</td><td>复用命中率、卸载驻留率</td><td>线性于 ρ</td><td>前缀缓存 + 分层卸载</td></tr><tr><td>通信缓冲</td><td>并行拓扑、NCCL/NIXL 通道</td><td>无关</td><td>按拓扑预留固定份额</td></tr></tbody></table>\n<p>用前面的算例套模板：若单卡 HBM 扣除权重、激活与通信缓冲后剩 40 GiB 可用作 KV，未压缩单请求 720 MiB 时并发上限约 56；ρ=0.25 后单请求 240 MiB，上限约 170。这就是“固定显存下提高并发批大小”的可复算含义。注意这个上限是理论上界，实际受分页碎片、复用命中波动与调度保守系数折损，工程上通常再打一个安全折扣。压缩比的选择因此不是精度与速度的二选一，而是在“KV 预算 ÷ 单请求 KV”这条式子上找使并发与 SLO 同时满足的 ρ 区间。</p>\n\n<h3 id=\"paper-duet-vlm-dual-stage-unified-efficien-2026-sec-25\">二十五 · 压缩比、精度与调度的联合约束</h3>\n<p>ρ 不能独立调。它与三个约束耦合：其一，KV 精度——FP8 KV 下 s=1，ρ 的显存收益按字节线性，但合并与剪枝掩码在低精度下的数值行为材料未给出证据，掩码若在量化后被扰动，训练与推理共享算子的分布一致性会被破坏，这是 DUET-VLM 的核心假设所面临的具体风险。其二，批调度粒度——ρN<sub>v</sub> 与 block 的对齐决定碎片，压缩过高使序列短到 block 利用率下降，压缩过低则节省有限。其三，显著性计算的算力代价——它随 N<sub>v</sub> 增长，ρ 越低意味着保留越少但打分仍需覆盖全量 token，单位保留 token 的算力成本上升。</p>\n<p>工程判断落在监控口径上：材料未给出压缩后 token 数与显存占用的监控指标，部署时必须自建三组观测——每请求压缩后长度分布、KV block 利用率与碎片率、显著性计算占预填时间的比例。这三组量共同决定 ρ 的安全上限；没有它们，压缩比只能靠离线扫描，无法在负载漂移时自适应。DUET-VLM 把 KV cache 分配粒度交给压缩后长度，这一步在账本上是清晰的；真正待补的是 ρ 与量化精度、批调度三者的匹配边界，以及失败模式下如何回退到未压缩路径而不破坏 SLO。</p>\n\n<h3 id=\"paper-duet-vlm-dual-stage-unified-efficien-2026-sec-26\">二十六 · 压缩比落进显存账本：KV 分配粒度与带宽拐点</h3>\n<p>DUET-VLM 对显存的真正贡献不在“少存了几个 token”，而在把 KV cache 的分配粒度从全量视觉长度改为 <span>k=⌊ρN⌋</span> 后的压缩长度。单请求 KV 占用可写成 <span class=\"formula\">$$M_{\\text{KV}}=2\\,L\\,H\\,d_h\\,(T_{\\text{txt}}+k)\\,b_{\\text{kv}}$$</span>，其中 L 为层数、H 为 KV 头数、d_h 为头维、b_kv 为每元素字节数（FP8 为 1、NVFP4 需按块缩放另计元数据）。压缩比 ρ 直接乘在视觉项上，文本项不动——这意味着长视频、高分辨率场景收益最大，而文本主导的短请求几乎不受益，ρ 调高对后者的边际回报迅速归零。工程判断是：ρ 必须与请求长度分布联合配置，而不是全局一个常数。</p>\n<p>带宽侧的拐点更隐蔽。解码阶段每步要读全部 KV，压缩后读取量按 k 缩减，但预填阶段两阶段算子本身要读全量 N 个 token 算相似度矩阵与显著性分数，这部分开销不随 ρ 下降。于是存在一个 ρ*：低于它，节省的 KV 带宽抵不过显著性计算的额外算力；高于它，关键视觉信息被剪掉、精度塌陷。材料未给出该拐点的定量位置，部署时只能用预填延迟预算做二分搜索式标定，把 ρ 当作可调参数而非固定超参。</p>\n<p>失效条件集中在三处。其一，可微掩码在 NVFP4/FP8 下数值精度可能破坏训练与推理的分布一致性——掩码是 0/1 硬门，量化后的显著性分数排序一旦翻转，top-k 集合在训练与部署间就不同，压缩算子共享即失效。其二，批调度按压缩后 token 数估算显存，若同一批内请求的 ρ 不同，显存估算需按最大 k 而非均值，否则会出现 OOM 抖动。其三，压缩过高时视觉 token 少于文本 token，KV 分配粒度被文本项主导，此时再压视觉已无显存收益，只剩精度代价。</p>\n<table class=\"mini\"><thead><tr><th>账本项</th><th>随 ρ 的变化</th><th>系统代价落点</th></tr></thead><tbody><tr><td>视觉 KV 容量</td><td>线性下降</td><td>并发批大小上限</td></tr><tr><td>预填算力</td><td>先降后平（算子开销固定）</td><td>首 token 延迟</td></tr><tr><td>解码 KV 带宽</td><td>线性下降</td><td>每步解码时延</td></tr><tr><td>显著性计算</td><td>不随 ρ 下降</td><td>预填额外算力</td></tr></tbody></table>\n<p>可复算的预算做法：给定层数、头数与头维，先算全量视觉 KV 字节数，再乘 ρ 得压缩后占用，加上文本 KV 与权重、激活峰值，与单卡 HBM3e 容量比对得出每卡可容纳请求数；随后用该请求数反推批调度上限，并与预填延迟预算对齐。材料未给出具体档位配置，因此这套账本只能定性给出结构，ρ 的安全上限必须在部署中实测标定，不能从论文结论直接外推。</p>\n<h3 id=\"paper-duet-vlm-dual-stage-unified-efficien-2026-sec-27\">二十七 · 压缩后 token 数作为调度原语</h3>\n<p>DUET-VLM 对调度系统最实质的贡献，是把“压缩比 ρ”从模型内部超参提升为调度器可直接读取的容量参数。传统多模态服务里，调度器只知道请求的原始分辨率与帧数，KV cache 预留按最坏情况估算；DUET-VLM 的两阶段算子把视觉 token 序列从 N 压到 k=⌊ρN⌋，压缩后的长度在预填开始前就已确定，于是调度器可以在准入控制阶段用压缩后长度而非原始长度做显存预留。这一改变的量级是线性的：单请求 KV 占用正比于 k，固定 HBM 下可并发批大小近似放大 1/ρ 倍（忽略权重与激活的固定开销）。</p>\n<p>但调度器不能把 ρ 当成免费旋钮。压缩比越高，单请求显存越小、批越大，然而第二阶段按注意力显著性保留 top-k，压缩过高会剪掉关键视觉证据，精度损失曲线材料未给出，部署时只能靠离线标定确定安全上限。工程上应把 ρ 作为分级配置而非全局常量：对短文本、单图请求用高压缩比换吞吐，对长文本、多帧视频请求保留较低压缩比，因为解码阶段 KV 带宽压力随文本长度增长而放大，视觉 token 的边际收益反而下降。</p>\n<div class=\"formula\">$$B_{\\max}\\approx\\left\\lfloor \\frac{M_{\\text{kv}}}{k\\cdot L_{\\text{txt}}\\cdot s_{\\text{kv}}} \\right\\rfloor,\\quad k=\\lfloor \\rho N \\rfloor$$</div>\n<p>其中 M_kv 为可用于 KV cache 的显存预算，L_txt 为文本 token 数，s_kv 为每 token 每层的 KV 字节数。这个式子说明压缩比与批大小不是独立可调的：ρ 减半，B_max 近似翻倍，但预填阶段每批的视觉 token 总算力并未同比下降，因为批变大了。调度器真正要优化的是“每 GPU 每秒完成的请求数”，而非单纯批大小。</p>\n\n<h3 id=\"paper-duet-vlm-dual-stage-unified-efficien-2026-sec-28\">二十八 · 连续批处理在压缩序列上的迭代粒度</h3>\n<p>连续批处理（continuous batching）的核心是解码步之间动态增删请求，迭代级调度而非请求级调度。DUET-VLM 的压缩序列对这一机制有两个具体影响。第一，预填长度分布变窄：原始视觉 token 数随分辨率线性增长，压缩后 k 的方差被 ρ 缩放，调度器做长度分桶时的桶边界更容易设定，分桶不均衡导致的 padding 浪费下降。第二，预填与解码的算力比例改变：压缩后预填 FLOPs 下降，单请求的解码步数相对占比上升，连续批处理中“解码主导”的批更容易形成，这对 Blackwell 上的 tcgen05 MMA 利用率和 TMEM 占用是好事——解码阶段的矩阵乘形状更规整，2-SM MMA 的配对效率更高。</p>\n<p>代价在于压缩算子的位置。第一阶段合并在视觉编码器侧、第二阶段剪枝在投影后，两者都发生在预填之前，因此它们不在连续批处理的迭代循环内，而是作为请求准入的前置步骤串行执行。这意味着压缩算子的延迟直接叠加在首 token 时延（TTFT）上，且无法被批处理摊薄——每个新请求都要单独跑一遍显著性打分。显著性分数计算的算力开销材料未给出定量对比，部署时必须把它计入 TTFT 预算，否则压缩收益会被前置开销抵消。</p>\n<ul>\n<li>机制：压缩在准入阶段完成，输出 k 与压缩后序列，调度器据此分配 KV 槽位。</li>\n<li>代价：显著性打分是每请求串行开销，压缩比越高、N 越大，该开销越显著。</li>\n<li>例子：视频请求帧数多导致 N 大，若逐帧独立打分，前置开销随帧数线性增长，需按批合并打分。</li>\n</ul>\n\n<h3 id=\"paper-duet-vlm-dual-stage-unified-efficien-2026-sec-29\">二十九 · chunked prefill 与压缩序列的切分点</h3>\n<p>chunked prefill 把长预填切成若干块，与解码步交错执行，目的是压低 TTFT 尾延迟并避免长预填阻塞解码。DUET-VLM 的压缩序列让切分点的选择变简单也变复杂。简单在于总长度 k 已知且远小于 N，块数减少，切分粒度可以放粗，减少了块间同步与 KV 写入的碎片。复杂在于压缩算子的两阶段结构：第一阶段合并必须在编码器输出上一次性完成（相似度矩阵需要全局近邻），第二阶段剪枝依赖投影后的注意力分数，两者都不能像文本预填那样任意切块。因此 chunked prefill 的切分只能发生在压缩之后的语言解码器预填段，压缩段本身是不可切的原子操作。</p>\n<p>工程判断是：把压缩段视为“预填的前置原子段”，为其单独预留时延预算，而不是试图把它塞进 chunk 流水线。若压缩段耗时超过单块预填预算，应改为按图像/帧分批压缩再拼接，用批内并行换取原子段缩短。这样做的代价是跨批的显著性分数归一化不再全局一致，需要在批间做分数重标定，否则 top-k 选择会偏向某一批。</p>\n<div class=\"formula\">$$T_{\\text{TTFT}}\\approx T_{\\text{merge}}+T_{\\text{proj}}+T_{\\text{prune}}+\\left\\lceil \\frac{k}{C} \\right\\rceil T_{\\text{chunk}}$$</div>\n<p>其中 C 为 chunk 大小。该式表明压缩段三项是加性的、不可与解码重叠，而预填块可与解码交错。压缩比提高使 k 下降、块数下降，但前三项不随 ρ 缩小——这是压缩在高吞吐档位上的固定成本下限。</p>\n\n<h3 id=\"paper-duet-vlm-dual-stage-unified-efficien-2026-sec-30\">三十 · 优先级、抢占与压缩比的联合决策</h3>\n<p>抢占（preemption）在显存不足时触发，通常做法是换出或重算被抢占请求的 KV。DUET-VLM 下抢占决策多了一个维度：被抢占请求的压缩后长度 k 决定了重算成本。重算意味着重新跑两阶段压缩算子加预填，成本正比于 N 而非 k——压缩段不可跳过。因此调度器在选牺牲者时，不能只看 KV 占用大小，还要看“重算代价/KV 节省”的比值：一个高 ρ、小 k 的请求虽然占显存少，但重算它要重跑全量 N 的合并与打分，性价比极低；反之低 ρ、大 k 的请求 KV 占用大但重算代价相对其节省的显存更划算。</p>\n<p>优先级调度应与压缩比联动：高优先级请求分配低压缩比以保证视觉证据完整，低优先级请求分配高压缩比以腾出并发空间。这形成一种软性分级——不是靠队列优先级硬隔离，而是靠压缩比调节单请求资源占用，使高优先级请求在同等显存下获得更多视觉 token 预算。代价是压缩比切换点需要标定，材料未给出压缩比与精度的定量边界，切换阈值只能靠离线评测确定，且切换本身会引入 token 分布不一致的风险，因为训练时按固定压缩比采样。</p>\n<table class=\"mini\"><thead><tr><th>抢占对象</th><th>KV 节省</th><th>重算代价</th><th>决策倾向</th></tr></thead><tbody><tr><td>高 ρ、小 k</td><td>小</td><td>高（重跑全量 N）</td><td>避免抢占</td></tr><tr><td>低 ρ、大 k</td><td>大</td><td>中（N 相同但 k 大）</td><td>优先抢占</td></tr><tr><td>文本长、视觉短</td><td>中</td><td>低（压缩段短）</td><td>可抢占</td></tr></tbody></table>\n\n<h3 id=\"paper-duet-vlm-dual-stage-unified-efficien-2026-sec-31\">三十一 · 分离式预填/解码下的压缩位置</h3>\n<p>分离式（disaggregated）预填/解码把预填与解码放到不同 GPU 池，中间通过 NVLink 5 或 NIXL 传输 KV。DUET-VLM 的压缩段应归属预填池：合并与剪枝都在预填侧完成，传输的是压缩后的 KV，而非全量视觉 KV。这直接降低跨池传输量——传输字节正比于 k 而非 N，在 NVLink 带宽固定时，单位时间可迁移的请求数上升，预填池与解码池的配比可以更偏向解码侧。这是压缩与分离式架构的天然契合点：压缩把“传输放大”问题在源头削掉。</p>\n<p>但传输的是压缩后 KV 意味着解码池无法回溯被剪掉的 token，若解码中途发现视觉证据不足，无法在解码侧重放压缩。这要求压缩比在预填侧一次定死，且显著性分数必须在预填池内完成归一化。工程上应把压缩比决策放在请求准入的路由层，由路由层根据请求类型、当前两池负载与 SLO 余量选定 ρ，再连同请求一起下发预填池。代价是路由层成为新的状态耦合点，ρ 的全局一致性依赖路由层与两池的配置同步；材料未给出监控口径，压缩后 token 数与显存占用的监控指标需在部署中补齐，否则 ρ 漂移无法被发现。</p>\n<ul>\n<li>机制：预填池执行两阶段压缩，跨池只传 k 长度的 KV，解码池按 k 分配缓存。</li>\n<li>公式：传输量 ∝ k·L_txt·s_kv，ρ 下降直接线性降低跨池带宽占用。</li>\n<li>代价：解码侧不可回溯剪枝，ρ 必须前置定死，路由层承担决策责任。</li>\n<li>例子：多帧视频请求在预填池压缩后传输量降至 1/ρ，解码池可接纳更多并发流。</li>\n</ul>\n\n<h3 id=\"paper-duet-vlm-dual-stage-unified-efficien-2026-sec-32\">三十二 · 尾延迟的压制路径</h3>\n<p>尾延迟（P99 TTFT）在多模态服务里由长视觉序列主导：少数高分辨率或长视频请求的 N 远大于均值，预填时间被它们拉长，连续批处理中这些长请求会占住批槽，拖慢同批其他请求。DUET-VLM 的压缩对尾延迟的作用是双面的。正面：k 随 ρ 缩放，长请求的预填块数下降，长尾被削短。负面：压缩段本身对长请求最重——N 越大，相似度矩阵与显著性打分的算力越大，且这段不可切分、不可与其他请求摊薄，反而可能成为新的长尾来源。</p>\n<p>压制路径有三条具体机制。其一，按 N 分档设定 ρ：N 越大用越高 ρ，使 k 的上界被压住，压缩段的算力增长被 ρ 部分抵消，但需接受大 N 请求的精度折损。其二，压缩段批内并行：把同批多个请求的显著性打分合并成一次大矩阵运算，用批维度摊薄固定开销，代价是分数归一化跨请求耦合，需按请求做行级 softmax 隔离。其三，为压缩段设独立超时与降级：超时则跳过第二阶段剪枝、直接用第一阶段合并结果，牺牲精度保 TTFT 上界。第三条是工程上最实用的兜底，因为它把不可切分的原子段变成了有界操作，代价是降级路径下的 token 分布偏离训练分布，精度不可预期，只能作为过载保护而非常态。</p>\n<p>最终判断落在压缩比与调度粒度的匹配边界上：材料未给出该边界，部署时应以“压缩段耗时 ≤ 单块预填预算”为约束反解 ρ 的上限，再以精度标定确定 ρ 的下限，两者夹出的区间才是可调度区间。区间为空意味着该硬件档位下压缩算子本身成为瓶颈，此时应优先优化显著性打分的批内并行，而非继续提高压缩比。</p>\n\n<h3 id=\"paper-duet-vlm-dual-stage-unified-efficien-2026-sec-33\">三十三 · 压缩比作为调度旋钮：连续批处理下的边界与代价</h3>\n<p>在连续批处理里，DUET-VLM 的压缩比 ρ 不只是精度参数，它直接改写调度器的显存账本。设单请求压缩后视觉 token 数为 k=⌊ρN⌋，文本 token 为 T，则单请求 KV 占用近似正比于 (k+T)·L·H·d，批大小 B 受限于显存上限 M：<div class=\"formula\">$$B_{\\max}\\approx\\left\\lfloor \\frac{M_{\\text{KV}}}{(k+T)\\cdot L\\cdot H\\cdot d\\cdot s}\\right\\rfloor$$</div>其中 s 为每元素字节数。ρ 降低使 k 线性下降，B_max 近似反比上升——这是压缩在 Blackwell 高吞吐档位上的主要收益来源，也是它失效的起点：调度器按压缩后长度分配 KV，一旦某请求在解码中途触发重算或回退到未压缩路径，显存账本立即失衡，必须靠抢占腾挪。</p>\n<p>chunked prefill 与两阶段压缩的耦合点在于分块粒度。第一阶段合并算子在编码器输出上按相似度合并近邻 token，其代价随 N² 的相似度矩阵增长；若把预填切成固定 token 块，块边界会切断近邻关系，合并质量下降。工程上应让分块边界对齐 patch 网格而非任意 token 数，否则压缩后序列在块间出现结构断裂，显著性分数在第二阶段失真。第二阶段的 top-k 剪枝本身是 O(N log k) 的选择操作，其算力开销在短请求上占比可观——当 N 较小、ρ 较高时，显著性计算的固定成本可能吃掉预填节省，这是压缩比不能无限下调的算力侧边界。</p>\n<p>优先级与抢占策略必须感知压缩状态。分离式预填/解码部署中，预填节点产出的是压缩后序列及其掩码，解码节点按 k 分配 KV 页；若解码侧发生抢占，被换出的请求保留压缩序列即可，重入时无需重跑视觉编码器——这是共享算子带来的调度红利。但量化档位会侵蚀它：NVFP4/FP8 下合并矩阵与剪枝掩码的数值精度若破坏训练期学到的分布一致性，压缩后 token 的显著性排序在部署侧漂移，调度器按错误长度估算显存，尾延迟随之抬升。材料未给出该兼容性证据，部署时应把压缩算子排除在低精度路径之外，或对其输出做高精度校验。</p>\n<table class=\"mini\"><thead><tr><th>调度参数</th><th>ρ 偏高</th><th>ρ 偏低</th></tr></thead><tbody><tr><td>KV 占用 / 批大小</td><td>占用高、B_max 小</td><td>占用低、B_max 大</td></tr><tr><td>预填延迟</td><td>长，尾延迟易超 SLO</td><td>短，但显著性开销占比升</td></tr><tr><td>关键信息风险</td><td>低</td><td>高，top-k 可能剪掉小目标</td></tr></tbody></table>\n<p>尾延迟的压制落在两处：一是把显著性分数计算移出关键路径，在预填分块内异步完成，用压缩后长度先占显存、后校正；二是对高优先级请求保留 ρ 的下限，禁止调度器为腾显存而临时提高压缩比——压缩比必须是请求级静态属性，动态调整会破坏训练与推理的同分布前提。监控口径需补齐压缩后 token 数与实际 KV 占用的比值，一旦偏离配置值即说明掩码或量化路径出了问题。</p>\n<h3 id=\"paper-duet-vlm-dual-stage-unified-efficien-2026-sec-34\">三十四 · 切分维度与压缩后序列的耦合</h3>\n<p>DUET-VLM 的压缩算子改变的不只是序列长度，而是并行切分的可行域。视觉 token 经第一阶段合并、第二阶段 top-k 剪枝后，序列长度从 N 降到 k=⌊ρN⌋，这个 k 直接进入语言解码器的预填张量形状，进而决定 TP 的切分粒度、PP 的层间激活体积、DP 的批内序列对齐方式。工程上要盯住的是：压缩比 ρ 与 TP 度数的乘积关系。若 TP=t，每卡分到的序列长度为 k/t，当 k/t 小于 MMA 指令的 N 维下限（tcgen05 的 tile 形状约束），张量并行反而引入填充浪费，算力利用率下降。因此压缩比不是越大越好，而是要与 TP 度数联合选取，使 k/t 落在 tile 整数倍附近。</p>\n<p>专家并行（EP）在 MoE 解码器上引入另一层约束：压缩后的 token 数决定路由后每个专家的平均 token 负载，k 越小，负载越不均，All-to-All 的尾延迟越突出。流水并行（PP）则受预填与解码阶段激活体积差异影响，压缩后预填激活变小，PP 的 micro-batch 数可以上调以填补流水气泡。数据并行（DP）在推理侧通常表现为副本复制，压缩比一致时各副本的批调度节奏才能对齐，否则副本间完成时间抖动会拉低整体吞吐。</p>\n<div class=\"formula\">$$\\text{tokens}_{\\text{per-rank}}=\\left\\lfloor \\frac{\\lfloor \\rho N\\rfloor}{t}\\right\\rfloor,\\quad \\text{util}\\propto \\frac{\\text{tokens}_{\\text{per-rank}}\\cdot d}{\\text{tile}_{N}}$$</div>\n<p>代价侧：TP 增大降低单卡显存但抬高 All-Reduce 通信量；EP 增大提升专家容量但抬高 All-to-All 带宽需求；PP 增大降低单卡层数但引入流水气泡。压缩比 ρ 下降时，这三条曲线同时移动，需要重新求解切分点。例子：一个视频请求帧数多、N 大，ρ 取中等值时 k 仍可观，TP=8 下每卡序列长度足以填满 tile；若换成长文本短图像的请求，N 小、k 更小，同一 TP=8 配置会出现大量填充，此时应降 TP 或合并请求成更大的批。</p>\n\n<h3 id=\"paper-duet-vlm-dual-stage-unified-efficien-2026-sec-35\">三十五 · NVLink 5 与 NVSwitch 的带宽账</h3>\n<p>Blackwell 档位的机内互连是 NVLink 5 加 NVSwitch，GB200/GB300 NVL72 把 72 个 GPU 置于同一 NVLink 域内，任意两卡之间可走单跳交换而非多跳。对推理而言，这意味着 TP 组与 EP 组可以跨机柜放置而不必担心拓扑不对称带来的集合通信抖动。但带宽账要按方向拆：All-Reduce 的通信量与参数量成正比，All-to-All 的通信量与 token 数乘以隐藏维度成正比。压缩算子削减的是 token 数，因此对 All-to-All 是直接减负，对 All-Reduce 几乎无影响——权重不变，梯度不传，推理期 All-Reduce 的字节数由模型规模锁定。</p>\n<p>这给出一个明确的工程判断：DUET-VLM 的压缩收益在 EP 主导的 MoE 解码器上放大，在 TP 主导的稠密解码器上被稀释。若部署形态是稠密模型加 TP=8，压缩后 token 数下降只减少预填算力与 KV 显存，集合通信的权重同步开销不变，端到端延迟的改善幅度受限于通信占比。反之，MoE 加 EP 的形态下，压缩直接削减 All-to-All 的 dispatch 与 combine 字节数，通信时间随 k 线性下降。</p>\n<table class=\"mini\"><thead><tr><th>集合操作</th><th>通信量随压缩的变化</th><th>受影响的主导并行</th><th>系统代价</th></tr></thead><tbody><tr><td>All-Reduce</td><td>基本不变（权重锁定）</td><td>TP</td><td>延迟占比随 k 下降而上升</td></tr><tr><td>All-to-All dispatch</td><td>随 k 线性下降</td><td>EP</td><td>带宽与尾延迟同步改善</td></tr><tr><td>All-to-All combine</td><td>随 k 线性下降</td><td>EP</td><td>返回路径字节减少</td></tr><tr><td>PP 点对点</td><td>随激活体积下降</td><td>PP</td><td>流水气泡可被更多 micro-batch 填补</td></tr></tbody></table>\n<p>例子：NVL72 域内做 EP=16 的 MoE 解码，压缩前每层 dispatch 的 token 数为 k₀，压缩后为 ρk₀，All-to-All 时间近似按 ρ 缩放；而同一请求若走 TP=8 稠密路径，All-Reduce 时间不变，压缩只体现在预填阶段。选路时应先判断解码器是稠密还是 MoE，再决定压缩比与并行维度的配比。</p>\n\n<h3 id=\"paper-duet-vlm-dual-stage-unified-efficien-2026-sec-36\">三十六 · All-to-All 的尾延迟与压缩比的非线性</h3>\n<p>All-to-All 的代价不是简单的字节数除以带宽。EP 路由后各专家收到的 token 数服从长尾分布，最慢的那个专家决定该层完成时间。压缩比 ρ 下降时，平均 token 数下降，但尾部的相对离散度可能上升——小样本下路由抖动更明显，少数专家仍收到不成比例的热 token。这意味着通信时间对 ρ 的响应是次线性的：字节数按 ρ 降，尾延迟按更慢的速率降，甚至在某些 ρ 区间出现平台期。</p>\n<p>缓解手段是容量因子与 token 丢弃策略的联合调参。容量因子放大每专家缓冲，降低溢出概率但抬高显存；压缩后 k 变小，容量因子的绝对值可以下调，二者存在替代关系。伪代码思路：对每层路由结果统计各专家 token 数的分位数，若 P99 超过容量因子的阈值，则对该层临时提高容量因子或触发 token 重排，把热专家的一部分 token 迁移到冷专家。这一步在压缩后序列上执行，计算量随 k 缩小，但重排本身引入一次额外的 All-to-All，需与预填延迟预算权衡。</p>\n<div class=\"formula\">$$T_{\\text{a2a}}\\approx \\frac{\\max_{e}\\;\\text{tokens}_{e}\\cdot d}{B_{\\text{nvlink}}}+T_{\\text{launch}},\\quad \\text{tokens}_{e}\\sim\\text{长尾}$$</div>\n<p>代价侧：尾延迟直接进入解码阶段的每 token 时间，SLO 约束下它比平均带宽更关键。例子：压缩比从高降到中，平均 token 数减半，但 P99 专家负载只降三成，All-to-All 时间改善有限；此时若把节省的显存用于增大批，批内多请求的路由叠加反而抹平了尾部离散，尾延迟才真正下降。这说明压缩比与批大小的联合配置比单独调 ρ 更有效。</p>\n\n<h3 id=\"paper-duet-vlm-dual-stage-unified-efficien-2026-sec-37\">三十七 · NIXL 传输与分离式预填/解码的边界</h3>\n<p>分离式预填/解码把预填与解码放在不同 GPU 池，KV cache 需跨池搬运，NIXL 承担这一传输。DUET-VLM 的压缩在这里有双重作用：预填侧产出的 KV 按压缩后长度分配，传输字节数随 ρ 下降；解码侧接收的 KV 块数减少，接收缓冲与显存碎片同步降低。但传输的启动开销与块粒度是固定的，当单请求 KV 体积小到接近块粒度时，压缩带来的字节节省被启动开销淹没，传输效率反而下降。</p>\n<p>工程判断：压缩比的选择要与 NIXL 的块大小对齐。若 KV 块按固定 token 数切分，压缩后每请求的块数应为整数且不过小，否则出现大量半空块，有效带宽利用率下降。伪代码思路：预填侧按压缩后长度计算块数 nb=⌈k·L·h·b/块字节⌉，若 nb 低于阈值则合并相邻请求的 KV 传输为一个批次，用批量传输摊薄启动开销。这一步要求批调度在预填侧就按压缩后 token 数分组，与调度层的批形成闭环。</p>\n<p>代价侧：跨池传输的延迟进入首 token 时间（TTFT），带宽占用影响解码池的并发容量。例子：图像请求压缩后 k 较小，单请求 KV 块数少，若逐请求传输则 NIXL 启动开销占比高；改为按批聚合传输后，TTFT 的传输分量下降，但聚合等待引入额外排队延迟，需在 SLO 的 TTFT 预算内取舍。</p>\n\n<h3 id=\"paper-duet-vlm-dual-stage-unified-efficien-2026-sec-38\">三十八 · 通信何时成为瓶颈的判据</h3>\n<p>判断通信是否主导，要看三个比值。其一，集合通信时间与计算时间之比：TP 下 All-Reduce 字节数固定，压缩后计算量降，比值上升，通信占比变大；EP 下 All-to-All 字节随 k 降，比值大致不变或下降。其二，压缩后每卡 token 数与 tile 下限之比：低于下限时填充浪费使计算时间虚高，通信反而显得不突出，这是假象，实际是算力利用率塌陷。其三，尾延迟与平均延迟之比：EP 路由长尾使 P99 远高于均值，SLO 按尾延迟定，此时通信是瓶颈而平均带宽账看不出。</p>\n<p>可操作的判据：在给定 ρ 与并行配置下，若 All-to-All 或 All-Reduce 时间占单层时间的比例超过计算时间，且压缩后该比例未随 ρ 下降而改善，则通信是瓶颈，应调整并行维度而非继续压低 ρ。反之若比例随 ρ 下降，说明压缩在有效减负，可继续调 ρ 直至 tile 下限约束出现。监控口径需补齐：材料未给出压缩后 token 数与显存占用的监控指标，部署时应至少记录每层 k、每卡 tokens_per-rank、集合通信时间与尾延迟分位数，才能把上述判据落地。</p>\n<p>例子：稠密解码器 TP=8 场景，压缩后计算时间降但 All-Reduce 不变，比例上升，此时正确动作是降 TP 或改用 EP 形态，而非把 ρ 压到更低导致精度风险。MoE 解码器 EP=16 场景，压缩后 All-to-All 字节降、尾延迟降，比例改善，可继续在 tile 约束内调 ρ。两种场景的判据相反，说明并行拓扑必须先于压缩比确定。</p>\n\n<h3 id=\"paper-duet-vlm-dual-stage-unified-efficien-2026-sec-39\">三十九 · 量化与掩码精度对通信路径的隐性影响</h3>\n<p>DUET-VLM 的两阶段算子以可微掩码实现，训练时梯度穿过合并矩阵与剪枝掩码回传。推理期若叠加 NVFP4/FP8 量化，掩码的数值表示成为通信路径上的隐性变量：剪枝掩码若以低精度存储，top-k 边界处的 token 选择可能与训练期不一致，导致压缩后序列分布偏移，进而使批调度的显存估算失准。合并矩阵在低精度下的舍入误差会累积到投影层输入，影响显著性分数的排序稳定性。</p>\n<p>工程上应把掩码与显著性分数保持在较高精度（如 FP16/BF16）参与选择决策，仅在进入 MMA 的激活与权重上用量化格式。这样通信传输的 KV 与激活是量化后的，但选择逻辑不量化，避免分布一致性被破坏。代价是掩码存储与比较操作的额外开销，材料未给出该开销与压缩收益的定量对比，部署时需与预填延迟预算联合评估。例子：NVFP4 下激活量化到 4 位，若显著性分数也降到 4 位，top-k 在分数接近的 token 间抖动，压缩后序列长度虽同但内容不同，KV cache 的块分布改变，NIXL 传输的块对齐假设失效，传输效率下降。保持分数高精度可消除这一抖动，代价是每层一次额外的比较与排序，计算量随 k 缩小而可控。</p>\n\n<h3 id=\"paper-duet-vlm-dual-stage-unified-efficien-2026-sec-40\">四十 · 压缩比落到并行切分上：DUET-VLM 的通信边界</h3>\n<p>DUET-VLM 的压缩比 ρ 不是只影响单卡显存，它同时改写了并行切分的形状。第一阶段在编码器输出上合并近邻 token，第二阶段在投影后按显著性保留 <span>k=⌊ρN⌋</span>，压缩后序列长度直接决定 KV cache 分配粒度与批调度估算口径。放到 TP/EP/PP/DP 上，问题变成：每层激活与 KV 的切分维度随 ρ 缩小，而权重切分不变，于是单卡计算量下降、集合通信量却未必同比例下降。以 All-Reduce 为例，单次通信量近似为 <span>2·(p−1)/p·M</span>（M 为待归约消息字节数），ρ 降低使 M 变小，但若 TP 组内仍按原拓扑同步，通信次数与同步点不变，通信占比反而上升——这正是压缩收益被并行开销吃掉的失效条件。</p>\n<p>具体机制上，视觉 token 压缩发生在预填前段，而语言解码器的 TP 切分覆盖全部层。压缩后序列短、每卡 GEMM 变小，NVLink 5 与 NVSwitch 上的 All-Reduce 延迟由固定同步开销主导而非带宽主导；此时提高 TP 度不再划算，应把省下的显存转给 DP 以提高并发批大小。反过来，若 ρ 过低导致序列过短，PP 的微批流水会出现气泡，PP 级数需与压缩后 token 数联合配置。EP 场景下，显著性剪枝使 token 分布更不均匀，All-to-All 的负载倾斜会放大尾延迟，NIXL 传输在分离式预填/解码间搬运压缩后 KV 时，消息变小、固定开销占比上升。</p>\n<table class=\"mini\"><thead><tr><th>ρ 区间</th><th>并行侧影响</th><th>系统代价</th></tr></thead><tbody><tr><td>偏高（压缩弱）</td><td>TP 仍受带宽约束</td><td>KV 显存与预填算力节省有限</td></tr><tr><td>适中</td><td>TP 降度、DP 升批</td><td>通信占比可控，批调度按压缩长度估算</td></tr><tr><td>偏低（压缩强）</td><td>PP 气泡、EP 倾斜</td><td>关键视觉信息损失，尾延迟上升</td></tr></tbody></table>\n<p>工程判断落在监控口径上：材料未给出压缩比与并行拓扑的匹配边界，也未给出 NVFP4/FP8 下合并与剪枝掩码的数值精度证据。部署时必须把压缩后 token 数、TP 组 All-Reduce 耗时占比、NIXL 传输消息尺寸三项并排监控；一旦通信占比随 ρ 下降而上升，说明并行度配置已越过拐点，应优先降 TP、升 DP，而不是继续压低压缩比。</p>\n<h3 id=\"paper-duet-vlm-dual-stage-unified-efficien-2026-sec-41\">四十一 · 精度塌陷：先分清是压缩比越界还是分布漂移</h3>\n<p>DUET-VLM 的精度塌陷在工程上有两种截然不同的成因，必须分开定位。第一种是压缩比越界：第二阶段按显著性保留 top-k，k=⌊ρN⌋，ρ 一旦越过安全上限，被剪掉的就不再是低信息 token，而是承载细粒度空间关系或小目标的 token，表现为模型对计数、位置、文字识别类问题答错，而对整体场景描述仍然正常。第二种是分布漂移：训练期按固定压缩比采样、推理期却按请求动态变化（例如长视频帧数暴涨导致实际 ρ 偏离训练采样区间），编码器没有见过这种压缩后分布，注意力显著性分数的排序本身失真，塌陷表现为输出变得“泛而空”、重复措辞增多。</p>\n<p>区分两者的诊断手段是双轨对照：固定一批探针请求，同时跑压缩路径与关闭第二阶段的对照路径，比较 top-k 掩码的 Jaccard 重叠率与最终答案的一致率。若掩码重叠率高但答案分歧大，问题在数值精度或量化兼容性；若掩码重叠率本身就低，问题在 ρ 与训练采样区间失配。监控口径上，必须把“实际压缩后 token 数 / 原始 token 数”的逐请求分布打点上报，而不是只报全局均值——均值会掩盖长视频请求把 ρ 拉爆的尾部。</p>\n<div class=\"formula\">$$\\text{drift}=\\frac{1}{B}\\sum_{b=1}^{B}\\left|\\rho_{\\text{serve}}^{(b)}-\\rho_{\\text{train}}\\right|,\\quad \\text{guard}:\\ \\text{drift}&gt;\\delta\\Rightarrow\\text{回退到}\\ \\rho_{\\text{train}}$$</div>\n<p>代价落在预填延迟上：对照路径意味着同一请求要跑两遍视觉编码器与投影，单请求预填算力翻倍，在 B200 档位上直接吃掉压缩带来的并发收益。因此对照只能按低采样率（如千分之一请求）触发，且必须放在独立流上，避免污染主批的调度节奏。</p>\n\n<h3 id=\"paper-duet-vlm-dual-stage-unified-efficien-2026-sec-42\">四十二 · OOM：KV 分配粒度与批估算口径不一致</h3>\n<p>DUET-VLM 的显存收益来自“KV cache 按压缩后长度分配”，但 OOM 恰恰常出在这句话的落地细节上。调度器在准入阶段用压缩后 token 数估算显存，而实际分配发生在预填之后；如果第一阶段的相似度合并是数据相关的（不同图像合并后的长度并不严格等于 ⌊ρN⌋ 的期望值），估算值与实际值之间就会出现逐请求偏差。批内偏差累积，加上解码阶段 KV 随生成长度继续增长，就会在批跑到中途时触发 OOM，而不是在准入时被拒。</p>\n<p>定位方法是把“准入估算 token 数”与“实际分配 token 数”的差值做成直方图，按图像分辨率与帧数分桶。若高分辨率桶的差值系统性偏正，说明合并算子的输出长度上界没有被正确建模，需要在准入公式里加一个按分辨率查表的安全余量。另一个常见来源是两阶段算子的临时缓冲：显著性分数矩阵在第二阶段要按 N×N 规模短暂存在，这部分显存不在 KV 预算内，却与 KV 争抢同一块 HBM。监控必须把算子临时缓冲单列一项，否则 OOM 会被误判为 KV 超配。</p>\n<table class=\"mini\"><thead><tr><th>观测项</th><th>正常形态</th><th>异常指向</th></tr></thead><tbody><tr><td>准入估算 − 实际分配</td><td>按分辨率分桶后近似零均值</td><td>系统性偏正 → 合并长度上界建模错误</td></tr><tr><td>算子临时缓冲峰值</td><td>随批内最大 N 线性</td><td>与 KV 同涨 → 第二阶段分数矩阵未复用</td></tr><tr><td>批内 KV 增长斜率</td><td>与生成长度线性</td><td>斜率突增 → 压缩掩码在解码期失效</td></tr></tbody></table>\n<p>回滚策略上，OOM 不应触发全局降级，而应先降批大小、再降 ρ、最后才关闭第二阶段。顺序不能反：先关第二阶段会让训练与推理分布立刻失配，精度塌陷比 OOM 更难恢复。</p>\n\n<h3 id=\"paper-duet-vlm-dual-stage-unified-efficien-2026-sec-43\">四十三 · 批抖动：压缩后长度方差直接放大调度噪声</h3>\n<p>连续批处理依赖请求长度的可预测性来做准入与拼批。DUET-VLM 把长度从“分辨率决定”变成“分辨率 × 内容 × ρ 共同决定”，方差显著变大：同一分辨率的两张图，一张纹理密集、一张大面积纯色，第一阶段合并后的长度可以差出可观比例。调度器若仍按分辨率档位估算，就会出现批内长度长尾，短请求被长请求拖住，表现为吞吐稳定但 P99 延迟抖动。</p>\n<p>诊断批抖动要看两个量：批内压缩后长度的变异系数，以及每轮迭代中“因长度超限被踢出的请求数”。前者高说明压缩算子的输出长度不可预测，后者高说明准入估算与实际的偏差已经影响到拼批决策。工程上可用的机制是把第一阶段合并后的长度作为请求元数据在准入前就实测出来——即把视觉编码器与合并算子前移到准入之前的轻量预跑阶段，用真实长度而非估算长度拼批。代价是编码器算力被提前占用，预填流水线需要多一级缓冲，但在高并发档位上换来的拼批质量通常值得。</p>\n<div class=\"formula\">$$\\text{CV}=\\frac{\\sigma(\\ell_{\\text{comp}})}{\\mu(\\ell_{\\text{comp}})},\\quad \\text{抖动代价}\\approx \\text{CV}\\cdot\\frac{\\bar{\\ell}_{\\max}-\\bar{\\ell}}{\\bar{\\ell}}$$</div>\n<p>具体例子：视频请求的帧数在时间维度上不均匀，某些帧几乎无运动，第一阶段会把大量近邻 token 合并掉，压缩后长度骤降；相邻的高运动帧则保留较多 token。若按固定帧数估算，批内长度分布呈双峰，调度器反复在“超配”与“欠配”之间摆动，这就是批抖动的典型形态。</p>\n\n<h3 id=\"paper-duet-vlm-dual-stage-unified-efficien-2026-sec-44\">四十四 · 尾延迟：显著性计算的算力在预填预算里被低估</h3>\n<p>第二阶段的显著性分数要算注意力，其算力随合并后序列长度 N 增长，而这段开销发生在预填之前、不在解码路径上，最容易被预填延迟预算漏掉。尾延迟的形态是：平均预填延迟因压缩而下降，但 P99 反而上升，因为少数长序列请求在第二阶段吃掉了全部节省下来的算力。定位时要把预填延迟拆成“编码器 + 第一阶段合并 + 投影 + 第二阶段剪枝 + 解码器预填”五段分别打点，看第二阶段是否在长序列桶里成为主项。</p>\n<p>机制上，显著性分数矩阵的计算可以用分块方式与合并算子流水重叠，避免串行等待；同时应对 N 设硬上限，超过上限的请求在准入阶段就被拆分或降采样，而不是让第二阶段在运行时爆掉预算。代价是分块带来额外的中间结果写回带宽，在 HBM 带宽紧张的批里会与 KV 读取争抢，需要按批的带宽占用动态调整分块大小。</p>\n<p>监控口径上，尾延迟必须与压缩比联合看：若 P99 上升同时 ρ 分布正常，问题在第二阶段算力；若 P99 上升且 ρ 分布向低压缩比偏移，说明调度器在压力下退回了保守压缩，等于放弃了 DUET-VLM 的收益。这两种情况的回滚动作完全不同，前者调分块与上限，后者调准入策略。</p>\n\n<h3 id=\"paper-duet-vlm-dual-stage-unified-efficien-2026-sec-45\">四十五 · 静默降级：掩码数值精度与量化兼容性</h3>\n<p>最危险的一类失败不报错、不 OOM、不抖动，只是精度缓慢下滑——静默降级。DUET-VLM 依赖可微掩码在训练时回传梯度，推理时掩码退化为硬 0/1；一旦叠加 NVFP4/FP8 量化，合并矩阵与剪枝掩码的数值表示会引入舍入，使“训练时见过的压缩后分布”与“部署时实际得到的分布”出现细微但系统性的偏移。这种偏移不会让单条请求明显出错，却会让整体准确率随批大小和量化档位漂移。</p>\n<p>诊断手段是掩码一致性检查：在相同输入下比较浮点参考路径与量化路径的 top-k 掩码，统计被翻转的 token 位置是否集中在显著性分数接近阈值的边界带。若翻转集中在边界带，说明是量化舍入导致的排序不稳，可通过提高显著性分数的累加精度或对边界带做保守保留来缓解。监控上应把“掩码翻转率”作为常驻指标，与准确率探针联合告警——只看准确率会被批间噪声掩盖，只看翻转率又无法判断是否真的影响输出。</p>\n<p>回滚路径上，静默降级不能靠重启解决，必须能按量化档位与压缩比两个维度独立回退：先回退量化档位验证是否为数值问题，再回退 ρ 验证是否为分布问题。这个二维回退矩阵需要在部署前就配好，否则现场只能整体关压缩，等于放弃全部收益。</p>\n<p>工程判断落在准入与监控的耦合上：DUET-VLM 的压缩比不是一个静态配置项，而是必须与批调度、量化档位、分辨率分布联合标定的运行时参数；把 ρ 当成常量下发、把监控只做成全局均值，是这套方案在 Blackwell 高吞吐档位上最现实的翻车方式。</p>\n\n<h3 id=\"paper-duet-vlm-dual-stage-unified-efficien-2026-sec-46\">四十六 · 失效边界：压缩比、掩码数值与批调度错配的三类塌陷</h3>\n<p>DUET-VLM 的压缩收益全部押在“训练与推理共享同一算子与阈值策略”上，这条假设一旦在部署侧松动，失效会以三种形态出现。其一是<strong>精度塌陷</strong>：第二阶段 TopK 的 k=⌊ρN⌋ 在训练期按固定压缩比采样，编码器适应的是该 ρ 下的 token 分布；若部署时为省显存把 ρ 调高，显著性分数排序尾部被截断，关键视觉 token 被剪掉，而语言解码器仍按训练期分布解码，输出退化为对图像细节的笼统描述。其二是<strong>静默降级</strong>：合并算子与剪枝掩码在 NVFP4/FP8 下参与前向，掩码的 0/1 语义经低精度量化后不再是硬门控，TopK 边界附近的 token 被“半保留”，压缩后序列长度名义上仍是 k，实际信息量与训练期不一致——这类偏差不报错、不崩，只表现为长尾样本准确率下滑。其三是<strong>批抖动与尾延迟</strong>：批调度按压缩后 token 数估算显存，而压缩比随图像分辨率与帧数浮动，同一批内请求的压缩后长度方差被放大，预填阶段出现长短请求混批，尾延迟由最长压缩序列决定。</p>\n<p>把三类失效统一到一个可观测口径上，需要把“名义压缩比”与“有效压缩比”分开记账。设请求 i 的全量视觉 token 数为 N_i、实际保留数为 k_i，则批内有效压缩比为</p>\n<div class=\"formula\">$$\\rho_{\\text{eff}}=\\frac{\\sum_i k_i}{\\sum_i N_i},\\qquad \\sigma_\\rho=\\operatorname{Std}\\!\\left(\\frac{k_i}{N_i}\\right)$$</div>\n<p>ρ_eff 偏离训练期 ρ 说明阈值策略漂移，σ_ρ 过大则预示批抖动。工程上应把 ρ_eff、σ_ρ、压缩后 KV 占用与预填 P99 延迟做成同一条监控曲线：ρ_eff 下滑而 P99 不降，说明显著性计算的额外算力已抵消压缩收益；σ_ρ 上升而吞吐不升，说明批调度粒度与压缩比未联合配置。回滚判据应绑定到 ρ_eff 与训练值的偏差阈值，而非等到端到端准确率报警——后者滞后太多。</p>\n<table class=\"mini\"><thead><tr><th>失效形态</th><th>可观测信号</th><th>定位手段</th><th>回滚动作</th></tr></thead><tbody><tr><td>精度塌陷</td><td>ρ_eff &gt; 训练 ρ，长尾样本准确率下滑</td><td>按分辨率/帧数分桶对比保留 token 的显著性分布</td><td>回退 ρ 至训练值，冻结阈值策略</td></tr><tr><td>静默降级</td><td>名义 k 不变但下游困惑度漂移</td><td>关闭量化重放同批请求，比对掩码硬门控前后序列</td><td>合并/剪枝算子退回高精度路径</td></tr><tr><td>批抖动</td><td>σ_ρ 升高、预填 P99 抬升、OOM 偶发</td><td>按压缩后长度分桶统计批内方差</td><td>改为按压缩后长度分桶组批，限缩最大批</td></tr></tbody></table>\n<p>OOM 在 DUET-VLM 里通常不是显存总量不足，而是 KV cache 按压缩后长度分配、而批调度仍按请求到达顺序组批造成的瞬时峰值：短压缩序列与长压缩序列混批时，预填激活与 KV 分配同时抬升。定位应抓“压缩后长度分桶 × 批大小”的二维热图，而非只看全局显存水位。回滚顺序也有讲究：先回退批调度策略（分桶组批），再回退压缩比，最后才动量化路径——因为前两者不改变算子语义，回滚代价最低；而量化路径回滚会同时破坏训练与推理的分布一致性，属于最后手段。监控口径必须在部署前补齐：材料未给出压缩后 token 数与显存占用的监控指标，这正是上线前必须自建的部分。</p>\n<h3 id=\"paper-duet-vlm-dual-stage-unified-efficien-2026-sec-47\">四十七 · 口径先于数字：这份材料能支撑什么结论</h3>\n<p>DUET-VLM 的公开材料里没有数据集名、没有基线配置、没有吞吐与精度数字，只有机制描述与一条压缩公式。因此本部分不提供任何“提升 X 倍”的读数，而是给出一个可复用的基准口径框架：当读者拿到一份声称在两阶段压缩下提速的报告时，应当按哪些维度去核对，哪些维度缺失就意味着数字不可比。对工程读者而言，最危险的不是数字小，而是数字背后的配置不可见——一个在固定 batch=1、单卡、FP16 下测出的预填延迟，与一个在 NVL72 机柜、连续批处理、NVFP4 权重下测出的吞吐，放进同一张表就是口径污染。</p>\n<p>基准口径至少要锁死五元组：模型（视觉编码器规模、语言解码器规模、是否 MoE）、硬件档位（B200 单卡 / B300 单卡 / GB200 NVL72 整柜）、batch 形态（静态批大小 vs 连续批处理下的并发请求数）、序列构成（文本 token 数与压缩后视觉 token 数之比）、指标定义（TTFT 是首 token 到达还是首 token 完成预填）。五元组任一维度不同，两个数字就不可直接相除。材料明确写“部署档位未给出”“并行拓扑未给出”“量化方案未给出”，这三条恰好对应五元组中的硬件、并行、精度三项，说明其结论只能定性表述为“压缩后长度下降带来预填算力与 KV 显存下降”，而不能换算成任何具体倍数。</p>\n<div class=\"formula\">$$\\text{可比性}=\\mathbb{1}[\\text{model}]\\cdot\\mathbb{1}[\\text{HW}]\\cdot\\mathbb{1}[\\text{batch}]\\cdot\\mathbb{1}[\\text{seq}]\\cdot\\mathbb{1}[\\text{metric}]$$</div>\n<p>这个指示函数不是修辞：任何一项为 0，两个读数之间的比值就没有物理意义。举例来说，把压缩比 ρ 从 0.5 提到 0.25，在 batch=1 的解码场景下 TPOT 可能几乎不变（解码受权重带宽约束，KV 读取量减半但权重读取不变），而在高并发预填场景下 TTFT 可能显著下降（预填是算力约束，token 数直接线性缩放 FLOPs）。同一组压缩比，两个指标给出两种故事，若报告只给一个“端到端吞吐提升”，读者无法判断它落在哪种负载形态上。</p>\n\n<h3 id=\"paper-duet-vlm-dual-stage-unified-efficien-2026-sec-48\">四十八 · 硬件档位：SM100 与 SM103 的差异必须写进表头</h3>\n<p>Blackwell 的 B200（SM100）与 B300（SM103）在推理基准里不能混为一档。二者共享 tcgen05 第五代张量核心、TMEM 与 2-SM MMA 的协作式矩阵乘形态，但 B300 在显存容量与带宽档位上更高，GB200/GB300 NVL72 则把单机内的 NVLink 5 域扩展到机柜级，使张量并行与专家并行的切分粒度可以跨节点。对 DUET-VLM 这类压缩后序列变短的负载，硬件档位的影响是双重的：一方面压缩降低了单请求的 KV 占用，使固定显存下并发批大小上升，这部分收益在显存越紧张的档位上越明显；另一方面压缩后每 token 的计算密度不变，2-SM MMA 的利用率取决于批内 token 总数是否足以填满 tile，压缩过度会让 GEMM 的 M 维变小、tensor core 空转。</p>\n<p>因此基准表头必须写明：卡型（B200/B300）、是否 NVL72 整柜、并行切分（TP/EP/PP 各几路）、互联是否走 NVLink 5 域内。材料写“并行拓扑未给出，材料未说明张量并行或专家并行切分方式”，这意味着即便未来给出吞吐数字，也无法判断它是单卡极限还是整柜聚合吞吐。工程判断上，压缩比与并行切分是耦合的：TP 越大，单卡上的注意力头数越少，压缩后序列变短会进一步稀释每卡的 GEMM 规模，通信占比上升；EP 场景下 MoE 路由的 token 分布会因视觉 token 被剪枝而改变，专家负载均衡需要重新评估。</p>\n<table class=\"mini\"><thead><tr><th>口径维度</th><th>必须记录</th><th>缺失时的后果</th></tr></thead><tbody><tr><td>硬件档位</td><td>SM100/SM103、单卡或 NVL72</td><td>吞吐不可跨档比较</td></tr><tr><td>并行拓扑</td><td>TP/EP/PP 路数与互联域</td><td>无法区分计算瓶颈与通信瓶颈</td></tr><tr><td>量化方案</td><td>权重/激活精度、是否 NVFP4/FP8</td><td>压缩算子数值行为未知</td></tr><tr><td>批形态</td><td>静态批大小或并发请求数</td><td>吞吐与延迟读数错配</td></tr></tbody></table>\n\n<h3 id=\"paper-duet-vlm-dual-stage-unified-efficien-2026-sec-49\">四十九 · batch 与并发：压缩比改变的是批调度粒度</h3>\n<p>DUET-VLM 的关键工程含义在于：压缩后的 token 数直接成为 KV cache 分配与批调度的粒度。传统连续批处理按“剩余显存能塞下多少 token”做准入决策，视觉 token 未压缩时，一张高分辨率图像可能占据数千 token 的 KV 预算，导致准入判断被单个长请求主导；压缩后视觉 token 数按 ρN 缩减，准入决策的方差变小，批内请求数可以更均匀。基准测试若只报“batch size”，而不报“并发请求数”与“每请求压缩后 token 数分布”，就无法复现这个效应。</p>\n<div class=\"formula\">$$B_{\\max}\\approx\\left\\lfloor\\frac{M_{\\text{KV}}}{L_{\\text{ctx}}\\cdot s_{\\text{kv}}\\cdot n_{\\text{req}}}\\right\\rfloor,\\quad L_{\\text{ctx}}=T_{\\text{text}}+\\lfloor\\rho N\\rfloor$$</div>\n<p>式中 M_KV 为可用于 KV 的显存，s_kv 为每 token 每层的 KV 字节数，n_req 为并发请求数。压缩比 ρ 下降使 L_ctx 下降，B_max 上升，但上升幅度取决于文本 token 与视觉 token 的比例：文本占主导的请求，压缩视觉 token 对 B_max 的边际贡献很小。这就是为什么基准必须报告序列构成。一个具体例子：同一批请求中若文本平均 512 token、视觉原始 2048 token，ρ=0.25 时视觉降到 512，L_ctx 从 2560 降到 1024，KV 预算减半以上；若文本平均 4096 token，同样压缩只把 L_ctx 从 6144 降到 4608，收益被文本稀释。报告若不拆这两个群体，平均吞吐的提升会被误读为压缩算子的普遍效力。</p>\n<p>代价侧同样要写清：压缩比越高，准入越宽松，但单请求的信息量下降，可能触发更多的重试或更长解码（模型在信息不足时倾向于生成更长的澄清性文本），这会反向拉高 TPOT 与总 token 数。材料未给出这一反馈回路的数据，部署时应把“压缩后 token 数”与“实际生成 token 数”同时纳入监控，否则吞吐读数会被生成长度的漂移污染。</p>\n\n<h3 id=\"paper-duet-vlm-dual-stage-unified-efficien-2026-sec-50\">五十 · 指标定义：TTFT、TPOT、吞吐、显存、功耗各自的口径陷阱</h3>\n<p>TTFT 在 VLM 场景下有两种定义：从请求到达到首 token 生成，或从预填开始到预填完成。前者包含图像预处理、patch 切分、视觉编码器前向与两阶段压缩的全部时间，后者只含语言解码器预填。DUET-VLM 的第一阶段合并在编码器侧、第二阶段剪枝在投影后，两阶段都落在 TTFT 的前半段，因此若报告用“预填完成”口径，会系统性低估压缩算子的开销。显著性分数计算引入额外算力，材料明确写“未给出该开销与压缩收益的定量对比”，这意味着 TTFT 的净收益是“预填 FLOPs 下降”减去“显著性打分开销”的差值，符号未知。</p>\n<p>TPOT 的口径陷阱在于是否含批内其他请求的干扰。连续批处理下，解码步的延迟由批内最大 KV 读取量决定，压缩后各请求 KV 长度不一，TPOT 的分布是长尾的；报平均值会掩盖尾延迟，而 SLO 通常约束的是 P99。吞吐则必须区分“请求吞吐”与“token 吞吐”：压缩降低了每请求的预填 token 数，若按 token 吞吐计，压缩本身会压低分子，只有按请求吞吐计才能体现并发收益。显存指标要区分峰值与稳态，两阶段压缩的中间张量（相似度矩阵、显著性分数）在预填期是瞬时峰值，可能抵消 KV 稳态节省。功耗指标在 NVL72 整柜口径下才有意义，单卡功耗与整柜功耗不可换算。</p>\n<ul>\n<li>TTFT：必须声明是否含视觉编码器与两阶段压缩，否则压缩开销被隐藏。</li>\n<li>TPOT：报 P50 与 P99 两条，批内 KV 长度异质时均值无意义。</li>\n<li>吞吐：请求/秒与 token/秒分开报，压缩场景下两者方向可能相反。</li>\n<li>显存：峰值（含压缩中间张量）与稳态 KV 占用分开报。</li>\n<li>功耗：单卡与整柜口径不可混，NVL72 下需注明是否含互联与交换。</li>\n</ul>\n\n<h3 id=\"paper-duet-vlm-dual-stage-unified-efficien-2026-sec-51\">五十一 · 哪些提升不可比：四类典型错配</h3>\n<p>第一类错配是精度档位不同。材料写“量化方案未给出，材料未说明 NVFP4/FP8 与压缩算子的兼容性”。若一份报告在 FP16 下测压缩收益，另一份在 NVFP4 下测，二者不可比：NVFP4 的块缩放粒度会改变合并算子中相似度计算的数值稳定性，剪枝掩码在低精度下的舍入可能破坏训练与推理的分布一致性。第二类错配是基线选择。单阶段剪枝的基线若在训练期未做压缩、推理期才剪枝，它本身就带有分布偏移惩罚，用它做分母会高估两阶段收益；正确基线应是同压缩比下的单阶段、且训练推理同分布。</p>\n<p>第三类错配是负载形态。预填密集型（长图像、短文本）与解码密集型（短图像、长文本）对压缩的敏感度完全不同，前者受益于 FLOPs 线性下降，后者受益于 KV 带宽下降但受权重带宽约束封顶。把两类请求混在一个平均吞吐里，等于把两种物理机制加权平均成一个没有解释力的数。第四类错配是硬件代际。SM100 与 SM103 的显存带宽档位不同，同一压缩比在两者上的 B_max 不同，跨代比值既含压缩收益又含硬件收益，无法分离。</p>\n<table class=\"mini\"><thead><tr><th>错配类型</th><th>表现</th><th>处理方式</th></tr></thead><tbody><tr><td>精度档位</td><td>FP16 对 NVFP4</td><td>同精度对比，或声明换算假设</td></tr><tr><td>基线选择</td><td>单阶段训练未压缩</td><td>用同压缩比、同分布基线</td></tr><tr><td>负载形态</td><td>预填密集混解码密集</td><td>按请求类型分层报告</td></tr><tr><td>硬件代际</td><td>SM100 对 SM103</td><td>同档对比，分离硬件增益</td></tr></tbody></table>\n<p>一个具体判断：若报告只给“端到端吞吐提升”，且未声明 batch 形态与序列构成，那么该数字最可能的解释是并发批大小上升带来的请求吞吐增益，而非单请求延迟改善。工程上应要求补充单请求 TTFT 与 P99 TPOT 两条曲线，才能判断压缩是否真的改善了 SLO 达标率，还是只是把队列深度换成了批宽度。</p>\n\n<h3 id=\"paper-duet-vlm-dual-stage-unified-efficien-2026-sec-52\">五十二 · 部署侧应补齐的监控口径</h3>\n<p>材料写“监控指标未给出，材料未说明压缩后 token 数与显存占用的监控口径”。在缺乏官方基准的情况下，部署团队应自行建立三组对照量：压缩前视觉 token 数 N 与压缩后 ⌊ρN⌋ 的逐请求记录，用于核对压缩算子是否按预期生效；预填阶段显著性打分的耗时占比，用于判断压缩开销是否吞掉收益；KV 稳态占用与峰值的比值，用于识别中间张量是否成为新的显存瓶颈。这三组量不需要新硬件，只需在调度器与显存分配器上打点。</p>\n<p>更进一步，压缩比应作为可调参数进入容量规划，而不是固定常量。给定 SLO 的 TTFT 预算与 P99 TPOT 预算，ρ 的选择是“预填 FLOPs 下降”与“信息损失导致的生成长度上升”之间的权衡；材料未给出精度损失曲线，因此安全上限只能通过在线 A/B 探测确定：以 ρ 的小步长扫描，观察任务级准确率与生成 token 数的拐点，拐点之前取最大 ρ。这个流程本身就是对“压缩比与批调度匹配边界未给出”这一局限的工程回应——把缺失的定量证据转化为部署期的自适应标定，而不是等待一份不可得的基准表。</p>\n<h3 id=\"paper-duet-vlm-dual-stage-unified-efficien-2026-sec-53\">五十三 · 迁移到非 ViT 视觉前端：合并算子的前提会塌</h3>\n<p>DUET-VLM 第一阶段能成立，依赖一个隐含前提：视觉编码器输出的是<strong>保序的 patch 网格</strong>，token 之间存在可度量的空间近邻关系，相似度合并才不会把不同区域的语义搅在一起。迁到 CNN 主干（如 ConvNeXt 类）时，特征图仍是网格，合并算子可以照搬，但通道语义与 ViT 不同，相似度矩阵的尺度需要重新标定；迁到早期融合或混合 Mamba 视觉塔时，token 序列不再具有显式二维邻接，第一阶段只能退化为全局相似度聚类，空间结构保留这一条直接失效。更麻烦的是可微性：合并矩阵若依赖硬分配（hard assignment），梯度只能通过 straight-through 近似回传，编码器侧的梯度方差会显著上升，训练稳定性下降。工程判断是——第一阶段的可迁移性取决于视觉塔是否输出网格化 token；不是网格，就不要硬套相似度合并，改为在投影后单点做显著性剪枝，把两阶段退化为单阶段，接受训练/推理分布一致性的损失。</p>\n<p>代价层面：合并算子本身要在编码器输出上算 <span>N×N</span> 相似度，N 为全量视觉 token 数。分辨率翻倍时 N 翻四倍，相似度矩阵算力按平方增长，这部分开销落在预填之前的预处理段，不占解码带宽但占 SM 时间。视频输入下帧数线性叠加，相似度计算成为预填前的新瓶颈。迁移到高帧率视频模型时，必须把第一阶段改成局部窗口内的近邻合并（只算 <span>w×w</span> 窗口），否则合并开销会吃掉压缩带来的预填收益。</p>\n\n<h3 id=\"paper-duet-vlm-dual-stage-unified-efficien-2026-sec-54\">五十四 · 迁到纯文本或音频：显著性分数的语义锚点不存在</h3>\n<p>第二阶段按注意力显著性保留 top-k，其分数来自跨模态投影后视觉 token 对文本 query 的注意力响应。这套机制迁到纯文本 LLM 时没有跨模态锚点，显著性只能退化为自注意力或位置先验，剪枝目标从“保留与问题相关的视觉证据”变成“保留语言流畅性所需 token”，两者不是同一个优化问题。迁到音频-文本模型时，音频 token 的时间邻接结构与图像 patch 的空间邻接不同，第一阶段的相似度合并要改成时间轴上的分段合并，压缩比 <span>ρ</span> 的物理含义从“空间降采样率”变成“时间降采样率”，对语音识别这类依赖细粒度时序的任务，压缩过高会直接抹掉音素边界。</p>\n<div class=\"formula\">$$k=\\lfloor \\rho N \\rfloor,\\quad \\text{TopK 的语义锚点}=\\text{跨模态 query 的注意力分布}$$</div>\n<p>判断标准很直接：第二阶段的剪枝是否有一个<strong>任务相关的 query 分布</strong>作为锚。有（VQA、图文检索、文档理解），显著性剪枝可迁移；没有（纯文本续写、无条件生成），显著性分数退化为噪声，剪枝等价于随机丢弃，精度损失不可控。这类场景应把第二阶段关掉，只保留第一阶段的结构性降采样，把压缩比控制在低档。</p>\n\n<h3 id=\"paper-duet-vlm-dual-stage-unified-efficien-2026-sec-55\">五十五 · 与量化精度的耦合：NVFP4/FP8 下掩码数值会破一致性</h3>\n<p>DUET-VLM 的核心卖点是训练与推理共享同一算子、同一阈值，从而保持 token 分布同分布。这个一致性在 FP16/BF16 下靠可微掩码维持；一旦部署档位切到 FP8 或 NVFP4，合并权重与剪枝显著性分数都要经过低精度量化，掩码的边界值（接近阈值的 token）会在量化舍入后翻转——训练时保留的 token 在推理时被剪掉，或反之。翻转比例随压缩比升高而放大，因为阈值附近的 token 密度在高压比下更高。这不是精度损失的常规问题，而是<strong>分布一致性的结构性破坏</strong>：训练期编码器适应的是掩码 A，推理期执行的是掩码 B，两者差异不体现在权重上，而体现在序列长度与内容上，KV cache 分配与批调度估算随之失配。</p>\n<p>工程上可行的做法是把阈值判定从低精度域剥离：显著性分数在 FP16 下算完、做 top-k 选择、生成布尔掩码，再把选中的 token 值量化送入后续算子。代价是掩码选择这一段保留高精度算力，不能完全吃满 FP8 的吞吐；收益是掩码在训练与推理间保持一致。若框架把整条链路压到 NVFP4，必须验证掩码翻转率，材料未给出该数据，部署前需自建对照：同一批请求在 BF16 与 NVFP4 下比较压缩后 token 数与内容重合度。</p>\n\n<h3 id=\"paper-duet-vlm-dual-stage-unified-efficien-2026-sec-56\">五十六 · 压缩比与批调度的匹配边界：上限由 SLO 与显存共同夹住</h3>\n<p>压缩后 token 数直接决定 KV cache 分配粒度与并发批大小，这条链路在容量规划上是双刃的。压缩比 <span>ρ</span> 提高，单请求 KV 占用按比例下降，固定显存下并发批大小上升；但预填阶段每请求的算力不再与序列长度成正比——显著性分数计算、top-k 选择、合并算子的固定开销构成一个与 <span>ρ</span> 弱相关的底噪。当 <span>ρ</span> 高到序列很短时，这部分底噪占比上升，预填延迟的下降曲线变平，吞吐增益饱和。</p>\n<table class=\"mini\"><thead><tr><th>压缩比档位</th><th>KV 显存</th><th>预填算力</th><th>批调度粒度</th><th>风险</th></tr></thead><tbody><tr><td>低（轻度降采样）</td><td>节省有限</td><td>接近全量</td><td>批大小提升小</td><td>收益不足以覆盖算子开销</td></tr><tr><td>中（结构+显著性）</td><td>显著下降</td><td>明显下降</td><td>批大小可上调</td><td>需验证精度边界</td></tr><tr><td>高（激进剪枝）</td><td>大幅下降</td><td>底噪占比上升</td><td>批大小受其他资源约束</td><td>关键视觉信息丢失、掩码翻转放大</td></tr></tbody></table>\n<p>规模上限的判断：压缩比的安全上界不由显存决定，而由<strong>任务对细粒度视觉证据的依赖度</strong>决定。文档 OCR、图表问答、小目标检测这类任务，token 冗余度低，高压比直接损失答案正确率；自然图像描述、粗粒度场景分类冗余度高，高压比可行。批调度的匹配边界则要求压缩比与调度器估算公式同步修改——调度器若仍按全量 token 数估算显存，压缩收益在批大小上体现不出来，等于白做。</p>\n\n<h3 id=\"paper-duet-vlm-dual-stage-unified-efficien-2026-sec-57\">五十七 · 不适用与需改造的场景清单</h3>\n<ul>\n<li><strong>高分辨率单图精细任务</strong>：token 冗余度低，第一阶段合并会把相邻但语义不同的 patch 混在一起，第二阶段显著性又难以区分细粒度证据，两阶段串联的误差叠加。建议只做第二阶段、低压缩比。</li>\n<li><strong>流式视频与长上下文</strong>：帧间冗余高，第一阶段可迁移，但相似度计算随帧数线性增长，需改为跨帧局部窗口合并；KV cache 按压缩长度分配后，跨帧注意力的一致性需重新验证。</li>\n<li><strong>多图交错输入</strong>：每张图的压缩比需独立配置，否则短图被过度压缩、长图压缩不足，批内 token 长度分布离散，调度器按均值估算会低估峰值显存。</li>\n<li><strong>量化部署链路</strong>：掩码高精度剥离是前提，材料未给兼容性证据，需自建翻转率对照。</li>\n<li><strong>训练侧复用</strong>：可微掩码要求梯度穿过合并矩阵与剪枝掩码，若下游框架不支持自定义反向，两阶段算子只能推理期使用，训练/推理一致性卖点失效。</li>\n</ul>\n<p>最后落在工程判断上：这套方案的可迁移性由两个条件夹住——视觉前端输出网格化 token，且任务存在任务相关的跨模态 query 分布。两个条件同时满足，两阶段压缩可以照搬，只需重标定相似度尺度与压缩比档位；缺一个，就退化为单阶段并接受分布一致性损失；缺两个，这套方案不适用，应转向纯结构性降采样或不做视觉 token 压缩。压缩比的安全上界必须在目标任务的精度曲线上实测确定，材料未给出该曲线，任何部署前的压缩比默认值都只能作为起点而非结论。</p>\n\n<h3 id=\"paper-duet-vlm-dual-stage-unified-efficien-2026-sec-58\">五十八 · 迁移与边界：压缩算子何时失效、何处必须重写</h3>\n<p>把 DUET-VLM 的两阶段压缩迁到别的模型，第一个要改的不是压缩比，而是<strong>第一阶段合并算子的邻域定义</strong>。它依赖视觉编码器输出 patch 序列的空间结构：ViT 类编码器有明确的二维网格，相似度合并可以按网格邻域做；换成早期卷积骨干加可变分辨率输入、或视频模型的时间维展开后，token 序列不再有稳定的空间索引，合并就得改成按特征距离的近似最近邻搜索，复杂度从邻域内比较升到全局候选筛选。这一步的代价直接落在预填延迟上：合并阶段本身是 O(N·邻域) 的相似度计算，N 随分辨率与帧数线性增长，若邻域退化为全局，算力开销会与它想节省的预填算力同量级。判断标准很直接——合并阶段耗时必须显著小于它替代掉的那部分预填耗时，否则压缩在端到端延迟上是负收益。</p>\n<p>第二个要改的是<strong>第二阶段显著性分数的来源</strong>。剪枝按注意力显著性保留 top-k，k=⌊ρN⌋，这要求投影层之后存在一个可靠的跨模态注意力参考。在编码器-解码器紧耦合、投影层与语言模型联合训练的多模态模型里，显著性分数与语言建模损失同源，剪枝掩码可微、梯度能回传；但在投影层冻结、或语言模型侧使用外部适配器的部署形态里，显著性分数只能来自推理期的近似注意力，掩码不可微，训练与推理共享同一算子的前提被打破，分布一致性随之丢失。此时应退化为固定压缩比的结构化剪枝，并接受精度漂移，而不是继续声称两阶段统一。</p>\n<div class=\"formula\">$$\\text{净收益}=\\underbrace{\\Delta T_{\\text{prefill}}+\\Delta M_{\\text{KV}}}_{\\text{压缩节省}}-\\underbrace{T_{\\text{merge}}+T_{\\text{saliency}}}_{\\text{算子开销}},\\quad \\text{需}\\ \\text{净收益}&gt;0\\ \\text{且}\\ \\Delta\\text{Acc}\\ \\text{在SLO内}$$</div>\n<p>规模上限由三件事共同决定，且都不是压缩比单独能调的。其一是<strong>KV cache 分配粒度</strong>：压缩后长度决定每请求显存，批调度按压缩后 token 数估算并发，压缩比 ρ 越高单请求占用越低，但 ρ 一旦越过关键视觉信息被剪掉的临界点，精度损失不可回传补偿，部署时无法从材料给出的信息确定安全上限，只能靠离线扫描 ρ 与精度的曲线来定。其二是<strong>量化兼容性</strong>：NVFP4/FP8 下合并矩阵与剪枝掩码的数值精度会破坏可微掩码训练出的分布一致性，压缩算子必须在量化前完成或用量化感知方式重训，否则高吞吐档位上的精度漂移会被批大小放大。其三是<strong>显著性计算的算力代价</strong>：它随压缩前序列长度增长，在视频多帧场景下可能抵消预填节省，需与预填延迟预算联合评估。下表给出迁移判断的边界条件。</p>\n<table class=\"mini\"><thead><tr><th>迁移对象</th><th>需改动</th><th>失效条件</th><th>系统代价</th></tr></thead><tbody><tr><td>无空间网格的编码器</td><td>合并改为特征近邻搜索</td><td>合并耗时接近预填节省</td><td>预填延迟上升</td></tr><tr><td>冻结投影层</td><td>退化为固定比结构化剪枝</td><td>掩码不可微，分布失配</td><td>精度漂移，需重标定</td></tr><tr><td>NVFP4/FP8 部署</td><td>量化感知重训或前置压缩</td><td>掩码数值精度破坏一致性</td><td>吞吐档位放大漂移</td></tr><tr><td>高帧数视频</td><td>显著性计算分块近似</td><td>算子开销抵消预填收益</td><td>净收益转负</td></tr></tbody></table>\n<p>不适用的情况要说清楚：当请求以短文本加单张小图为主、视觉 token 占比本就很低时，两阶段算子的固定开销摊不平，压缩带来的 KV 节省不足以改变批大小档位，此时直接跳过压缩更稳；当 SLO 由解码阶段 KV 带宽而非预填算力主导时，压缩只降低预填与显存，对解码吞吐的边际贡献有限，收益被高估。工程判断应落在监控口径上：部署必须同时记录压缩后 token 数、合并与显著性算子耗时、以及每档 ρ 下的精度与并发批大小，三者缺一就无法判定净收益符号，也就无法给出安全的规模上限。</p>\n<figure class=\"diagram\" data-fig=\"paper-family\"><svg style=\"max-width:746px;margin:0 auto\" xmlns=\"http://www.w3.org/2000/svg\" viewBox=\"0 0 746.0 138\" preserveAspectRatio=\"xMidYMid meet\" role=\"img\"><text x=\"136.0\" y=\"32.0\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"10.5\" fill=\"#68727d\" font-weight=\"600\" text-anchor=\"middle\">上游 · 站在谁肩上</text><rect x=\"38.0\" y=\"44.0\" width=\"196.0\" height=\"35.0\" rx=\"6\" fill=\"#fdf3e3\" stroke=\"#ecd9b8\" stroke-width=\"1.2\"/><text x=\"48.0\" y=\"61.0\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"12.0\" fill=\"#b45309\" font-weight=\"500\" text-anchor=\"start\">领域入口（无上游）</text><text x=\"380.0\" y=\"32.0\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"10.5\" fill=\"#68727d\" font-weight=\"600\" text-anchor=\"middle\">本文</text><rect x=\"282.0\" y=\"44.0\" width=\"196.0\" height=\"52.0\" rx=\"6\" fill=\"#e9eff5\" stroke=\"#d6e2ec\" stroke-width=\"1.2\"/><text x=\"292.0\" y=\"61.0\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"12.0\" fill=\"#163a5a\" font-weight=\"500\" text-anchor=\"start\">DUET-VLM: Dual stage </text><text x=\"292.0\" y=\"78.0\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"12.0\" fill=\"#163a5a\" font-weight=\"500\" text-anchor=\"start\">Unified Efficient …</text><text x=\"624.0\" y=\"32.0\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"10.5\" fill=\"#68727d\" font-weight=\"600\" text-anchor=\"middle\">下游 · 被谁接走</text><rect x=\"526.0\" y=\"44.0\" width=\"196.0\" height=\"35.0\" rx=\"6\" fill=\"#e8f5ec\" stroke=\"#cde9d5\" stroke-width=\"1.2\"/><text x=\"536.0\" y=\"61.0\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"12.0\" fill=\"#15803d\" font-weight=\"500\" text-anchor=\"start\">暂无下游记录</text><line x1=\"238.0\" y1=\"74.0\" x2=\"271.0\" y2=\"74.0\" stroke=\"#d8d3c6\" stroke-width=\"1.4\"/><path d=\"M 270.0 69.5 L 270.0 78.5 L 278.0 74.0 Z\" fill=\"#d8d3c6\"/><line x1=\"482.0\" y1=\"74.0\" x2=\"515.0\" y2=\"74.0\" stroke=\"#d8d3c6\" stroke-width=\"1.4\"/><path d=\"M 514.0 69.5 L 514.0 78.5 L 522.0 74.0 Z\" fill=\"#d8d3c6\"/><text x=\"380.0\" y=\"128.0\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"11.0\" fill=\"#68727d\" font-weight=\"400\" text-anchor=\"middle\">2026 · arXiv preprint</text></svg><figcaption><b>家谱</b> · DUET-VLM: Dual stage Un… 的上游问题、本文位置与下游继承；箭头表示方法/问题的传递，不是时间先后。</figcaption></figure>\n<table class=\"mini\" data-fig=\"paper-exp\"><caption>实验速查：这篇论文拿什么数据、和谁比、提升来自哪里</caption><thead><tr><th>项</th><th>内容</th></tr></thead><tbody><tr><td>数据集</td><td>未给出</td></tr><tr><td>基线</td><td>未给出</td></tr><tr><td>主要结果</td><td>材料未给出具体数据集与基线数字，仅说明两阶段压缩在训练与推理共享同一算子，…</td></tr><tr><td>消融</td><td>材料未给出消融实验；仅可推断两阶段相对单阶段的必要性在于训练与推理分布一致…</td></tr><tr><td>局限</td><td>材料未给出压缩比上限、精度损失曲线与失败模式；两阶段算子的额外开销、显著性…</td></tr></tbody></table>\n<p class=\"paper-line\">本页对应：papers/paper-duet-vlm-dual-stage-unified-efficien-2026 · 共 9 个片段</p>\n";break;}}})();
